package com.nexo.kotoba

import android.content.Context

data class KanaChar(val id: String, val kana: String, val romaji: String, val mnemonic: String)

data class Word(
    val id: String,
    val emoji: String,
    val kana: String,
    val romaji: String,
    val kanji: String = "",
    val en: String,
    val ipa: String,
    val hi: String = ""
)

data class Lesson(
    val id: String,
    val title: String,
    val emoji: String,
    val desc: String,
    val words: List<Word>,
    val lang: String = "ja",
    val level: String = "",
    val source: String = ""
)

data class Phrase(
    val id: String,
    val emoji: String,
    val ja: String,
    val romaji: String,
    val en: String,
    val chunks: String,
    val hi: String = ""
)

data class PatternExample(
    val emoji: String,
    val ja: String,
    val romaji: String,
    val en: String,
    val hi: String = ""
)

data class Pattern(
    val id: String,
    val titleEn: String,
    val titleJa: String,
    val lang: String,
    val ruleEn: String,
    val ruleJa: String,
    val examples: List<PatternExample>,
    val ruleHi: String = "",
    val level: String = "",
    val source: String = ""
)

data class Sentence(
    val id: String,
    val emoji: String,
    val ja: String,
    val romaji: String,
    val en: String,
    val hi: String = ""
)

data class SentenceCategory(
    val id: String,
    val title: String,
    val emoji: String,
    val desc: String,
    val sentences: List<Sentence>,
    val lang: String = "ja"
)

data class KanjiChar(
    val id: String,
    val kanji: String,
    val meaning: String,
    val onyomi: String,
    val kunyomi: String,
    val jlpt: String,
    val grade: Int,
    val strokes: Int
)

data class AlphabetChar(
    val letter: String,
    val word: String,
    val emoji: String,
    val ipa: String,
    val kana: String,
    val hi: String
)

