    val allWords: List<Word> = allLessons.flatMap { it.words }

    val allPhrases = listOf(
        Phrase("p1", "👋", "こんにちは、おげんきですか。", "konnichiwa, ogenki desu ka", "Hello, how are you?", "こんにちは (hello) + おげんきですか (are you well?)"),
        Phrase("p2", "🙏", "ありがとうございます。", "arigatou gozaimasu", "Thank you very much.", "ありがとう (thank you) + ございます (polite)"),
        Phrase("p3", "🚻", "すみません、トイレはどこですか。", "sumimasen, toire wa doko desu ka", "Excuse me, where is the restroom?", "トイレ (restroom) は (topic) どこ (where) ですか (is?)"),
        Phrase("p4", "💰", "これはいくらですか。", "kore wa ikura desu ka", "How much is this?", "これ (this) は (topic) いくら (how much) ですか (is?)"),
        Phrase("p5", "🐱", "わたしはねこがすきです。", "watashi wa neko ga suki desu", "I like cats.", "わたし (I) は (topic) ねこ (cat) が (subject) すき (like) です (is)"),
        Phrase("p6", "📚", "にほんごをべんきょうしています。", "nihongo wo benkyou shite imasu", "I'm studying Japanese.", "にほんご (Japanese) を (object) べんきょうして (studying) います (ongoing)"),
        Phrase("p7", "🏃", "まいにちうんどうします。", "mainichi undou shimasu", "I exercise every day.", "まいにち (every day) うんどう (exercise) します (do)"),
        Phrase("p8", "🎬", "あしたえいがをみます。", "ashita eiga wo mimasu", "I'll watch a movie tomorrow.", "あした (tomorrow) えいが (movie) を (object) みます (watch)"),
        Phrase("p9", "🍜", "たべものはおいしいです。", "tabemono wa oishii desu", "The food is delicious.", "たべもの (food) は (topic) おいしい (delicious) です (is)"),
        Phrase("p10", "🚆", "でんしゃでいきます。", "densha de ikimasu", "I'll go by train.", "でんしゃ (train) で (by means of) いきます (go)"),
        Phrase("p11", "⏳", "ちょっとまってください。", "chotto matte kudasai", "Please wait a moment.", "ちょっと (a little) まって (wait) ください (please)"),
        Phrase("p12", "💝", "すきなものはなんですか。", "sukina mono wa nan desu ka", "What's your favorite thing?", "すきな (favorite) もの (thing) は (topic) なん (what) ですか (is?)"),
        Phrase("p13", "🌅", "おはようございます。", "ohayou gozaimasu", "Good morning.", "おはよう (morning) + ございます (polite)", "शुभ प्रभात।"),
        Phrase("p14", "🍽️", "いただきます。", "itadakimasu", "Let's eat! (before a meal)", "いただきます = humble form of 'I receive'", "खाने से पहले कहा जाने वाला धन्यवाद।"),
        Phrase("p15", "🙏", "ごちそうさまでした。", "gochisousama deshita", "Thanks for the meal.", "ごちそうさま (feast) + でした (past polite)", "खाने के बाद धन्यवाद।"),
        Phrase("p16", "🌙", "おやすみなさい。", "oyasuminasai", "Good night.", "おやすみ (rest) + なさい (soft command)", "शुभ रात्रि।"),
        Phrase("p17", "👋", "またあした。", "mata ashita", "See you tomorrow.", "また (again) + あした (tomorrow)", "कल मिलते हैं।"),
        Phrase("p18", "📛", "なまえはなんですか。", "namae wa nan desu ka", "What's your name?", "なまえ (name) は (topic) なん (what) ですか (is?)", "आपका नाम क्या है?"),
        Phrase("p19", "📍", "どこからきましたか。", "doko kara kimashita ka", "Where are you from?", "どこ (where) から (from) きました (came) か (?)", "आप कहाँ से हैं?"),
        Phrase("p20", "🗣️", "にほんごがすこしわかります。", "nihongo ga sukoshi wakarimasu", "I understand a little Japanese.", "にほんご (Japanese) が (subject) すこし (a little) わかります (understand)", "मुझे थोड़ी जापानी समझ आती है।"),
        Phrase("p21", "🔁", "もういちどおねがいします。", "mou ichido onegaishimasu", "One more time, please.", "もういちど (once more) おねがいします (please)", "एक बार फिर, कृपया।"),
        Phrase("p22", "🍻", "かんぱい！", "kanpai!", "Cheers!", "かんぱい = dry cup → 'cheers'", "चियर्स!"),
        Phrase("p23", "👍", "それはいいですね。", "sore wa ii desu ne", "That's nice, isn't it.", "それ (that) は (topic) いい (good) ですね (right?)", "यह बहुत अच्छा है।"),
        Phrase("p24", "🌏", "どこでしゅっしんですか。", "doko de shusshin desu ka", "Where are you originally from?", "どこ (where) で (in) しゅっしん (origin) ですか (is?)", "आपका गृहस्थान कहाँ है?")
    )

    val allPatterns = listOf(
        Pattern(
            "jp1", "A は B です — 'A is B'", "A は B です — 「AはBです」", "ja",
            "USAGE: は (wa) marks the topic of the sentence, and です (desu) means 'is/am/are'. Together they form the basic Japanese sentence skeleton: A は B です = 'A is B'. Nearly every Japanese sentence starts by stating a topic.\nWHEN: Use it to introduce yourself, describe things, and say what something is: わたしはがくせいです (I am a student), きょうはあめです (Today is rainy). は is written 'ha' but pronounced 'wa'.\nFORM: [topic] は [noun/adjective] です. Negative: じゃないです / ではありません. Past: でした. Question: add か at the end.\nTIP: The topic is whatever you are talking about — a person, place, time or thing. When the topic is clear from context, Japanese often drops it entirely.",
            "用途: は は文の「話題」を示し、です は「〜です（である）」の意味です。この2つで「AはBです」という日本語の基本の文型ができます。ほぼすべての日本語の文は、まず話題を述べるところから始まります。\nいつ: 自己紹介や物の説明、名前・職業・状態を言うときに使います。わたしはがくせいです、きょうはあめです。は は「わ」と発音します。\n形: [話題] は [名詞・形容詞] です。否定: じゃないです / ではありません。過去: でした。疑問: 文末に か。\nヒント: 話題が文脈から明らかなとき、日本語では主語がよく省略されます。",
            listOf(
                PatternExample("👩", "わたしはせんせいです。", "watashi wa sensei desu", "I am a teacher."),
                PatternExample("📖", "これはほんです。", "kore wa hon desu", "This is a book."),
                PatternExample("🐱", "ねこはかわいいです。", "neko wa kawaii desu", "Cats are cute.")
            ),
            "उपयोग: は (wa) वाक्य का विषय दिखाता है, और です का अर्थ है 'है/हूँ'। इनसे बनता है मूल वाक्य-ढाँचा: A は B です = 'A ही B है'। लगभग हर जापानी वाक्य विषय बताने से शुरू होता है।\nकब: परिचय देने, चीज़ों का वर्णन करने और कुछ 'है' बताने के लिए: わたしはがくせいです (मैं विद्यार्थी हूँ), きょうはあめです (आज बारिश है)। は लिखा 'ha' है पर बोला 'wa' जाता है।\nरूप: [विषय] は [संज्ञा/विशेषण] です। नकारात्मक: じゃないです / ではありません। भूतकाल: でした। प्रश्न: अंत में か।\nटिप: विषय स्पष्ट हो तो जापानी में उसे अक्सर हटा देते हैं।"
        ),
        Pattern(
            "jp2", "～ではありません — 'is not'", "～ではありません — 「〜ではありません」", "ja",
            "USAGE: ではありません means 'is not'. It is the polite negative of です and is the standard way to deny something in Japanese.\nWHEN: Use it to say what something is NOT: わたしはがくせいではありません (I am not a student). じゃないです is the slightly more casual version, common in daily speech.\nFORM: [noun] ではありません | casual: [noun] じゃないです. Past: ではありませんでした.\nTIP: Adjectives form their negative differently (い-adjectives: たかい → たかくないです), so this form is mainly used with nouns.",
            "用途: ではありません は「〜ではない」という意味で、です の丁寧な否定形です。日本語で何かを否定する標準的な言い方です。\nいつ: 「〜ではない」と言いたいときに使います。わたしはがくせいではありません。くだけた言い方では じゃないです。\n形: [名詞] ではありません | くだけた形: [名詞] じゃないです。過去: ではありませんでした。\nヒント: 形容詞の否定は別の形になります（たかい → たかくないです）。この形は主に名詞に使います。",
            listOf(
                PatternExample("🐶", "ねこではありません。", "neko dewa arimasen", "It's not a cat."),
                PatternExample("🎓", "わたしはがくせいではありません。", "watashi wa gakusei dewa arimasen", "I'm not a student.")
            ),
            "उपयोग: ではありません का अर्थ है 'नहीं है' — です का विनम्र नकारात्मक रूप। जापानी में इनकार का मानक तरीका।\nकब: बताने के लिए कि कुछ 'नहीं है': わたしはがくせいではありません (मैं विद्यार्थी नहीं हूँ)। कैज़ुअल रूप: じゃないです।\nरूप: [संज्ञा] ではありません | कैज़ुअल: じゃないです। भूतकाल: ではありませんでした।\nटिप: विशेषणों का नकारात्मक अलग होता है (たかい → たかくない), यह रूप मुख्यतः संज्ञा के लिए।"
        ),
        Pattern(
            "jp3", "～ですか — question", "～ですか — 「〜ですか」", "ja",
            "USAGE: Adding か (ka) to the end of a sentence turns it into a yes/no question. No word order change is needed.\nWHEN: Use it whenever you want to ask 'is it ~?', 'do you ~?': がくせいですか (Are you a student?). Raise the intonation at the end, like in English.\nFORM: [sentence] か. Example: きょうはあめですか = Is it rainy today?\nTIP: か questions are answered with はい (yes) or いいえ (no). You can also attach か directly to a noun without です: にほんじんですか.",
            "用途: 文末に か を付けるだけで、その文が「はい・いいえ」で答える疑問文になります。語順は変わりません。\nいつ: 「〜ですか？」と聞きたいとき。がくせいですか。語尾を上げて発音します。\n形: [文] か。きょうはあめですか = 今日は雨ですか。\nヒント: 答えは はい（肯定）か いいえ（否定）。名詞に直接 か を付けて聞くこともできます。",
            listOf(
                PatternExample("🖊️", "これはペンですか。", "kore wa pen desu ka", "Is this a pen?"),
                PatternExample("🫂", "おげんきですか。", "ogenki desu ka", "How are you? (Are you well?)")
            ),
            "उपयोग: वाक्य के अंत में か (ka) लगाते ही वह हाँ/नहीं वाला प्रश्न बन जाता है। शब्द-क्रम नहीं बदलता।\nकब: पूछने के लिए 'क्या ~ है?' या 'क्या आप ~ हैं?': がくせいですか (क्या आप विद्यार्थी हैं?)। स्वर ऊपर उठाएँ।\nरूप: [वाक्य] か। きょうはあめですか = क्या आज बारिश है?\nटिप: उत्तर はい (हाँ) या いいえ (नहीं)। संज्ञा के बाद सीधे か भी लगा सकते हैं।"
        ),
        Pattern(
            "jp4", "～がすきです — 'I like ~'", "～がすきです — 「〜が好きです」", "ja",
            "USAGE: すき (suki) means 'like'. It behaves like an adjective, and the thing you like is marked with が (ga).\nWHEN: Say what you like or dislike: ねこがすきです (I like cats), さかなはすきじゃないです (I don't like fish). だいすき means 'love'.\nFORM: [thing] が すき です. Negative: すきじゃないです. Past: すきでした.\nTIP: The object of liking takes が, not を — this surprises many learners. Remember: すき always pairs with が.",
            "用途: すき は「好き」という意味の形容詞のような言葉です。好きなものを が で示します。\nいつ: 好き・嫌いを言うとき。ねこがすきです、さかなはすきじゃないです。だいすき は「大好き」。\n形: [もの] が すき です。否定: すきじゃないです。過去: すきでした。\nヒント: 好きの対象は を ではなく が で示します。ここがよく間違えるポイントです。",
            listOf(
                PatternExample("🐟", "さかな が すきです。", "sakana ga suki desu", "I like fish."),
                PatternExample("🇯🇵", "にほんご が すきです。", "nihongo ga suki desu", "I like Japanese.")
            ),
            "उपयोग: すき का अर्थ है 'पसंद'। यह विशेषण जैसा काम करता है, और जो पसंद है उसे が से चिह्नित करते हैं।\nकब: पसंद/नापसंद बताने के लिए: ねこがすきです (मुझे बिल्लियाँ पसंद हैं), さかなはすきじゃないです (मुझे मछली पसंद नहीं)। だいすき = 'बहुत पसंद'।\nरूप: [चीज़] が すき です। नकारात्मक: すきじゃないです। भूतकाल: すきでした।\nटिप: पसंद की चीज़ के साथ を नहीं, が लगता है — यही आम गलती है।"
        ),
        Pattern(
            "jp5", "～を たべます / のみます — object + action", "～を たべます / のみます — 「〜を食べます・飲みます」", "ja",
            "USAGE: The particle を (o) marks the direct object of a verb. たべます = 'eat', のみます = 'drink'.\nWHEN: Use it whenever an action happens to a thing: パンをたべます (I eat bread), みずをのみます (I drink water).\nFORM: [object] を [verb]. In Japanese the verb always comes at the end of the sentence.\nTIP: を is pronounced 'o', not 'wo'. When the object is obvious, Japanese often drops it: たべます by itself can mean 'I eat (it)'.",
            "用途: 助詞 を は動作の対象（目的語）を示します。たべます=食べる、のみます=飲む。\nいつ: 何かを「食べる・飲む」など動作が及ぶときに。パンをたべます、みずをのみます。\n形: [対象] を [動詞]。日本語では動詞は文の最後に来ます。\nヒント: を は「お」と発音します。対象が明らかなときは省略されることもあります。",
            listOf(
                PatternExample("🍎", "りんごをたべます。", "ringo wo tabemasu", "I eat an apple."),
                PatternExample("💧", "みずをのみます。", "mizu wo nomimasu", "I drink water.")
            ),
            "उपयोग: कण を (o) क्रिया के कर्म (direct object) को दिखाता है। たべます = 'खाना', のみます = 'पीना'।\nकब: जब क्रिया किसी चीज़ पर हो: パンをたべます (मैं रोटी खाता हूँ), みずをのみます (मैं पानी पीता हूँ)।\nरूप: [कर्म] を [क्रिया]। जापानी में क्रिया हमेशा वाक्य के अंत में।\nटिप: を को 'o' बोलते हैं ('wo' नहीं)। कर्म स्पष्ट हो तो उसे छोड़ देते हैं।"
        ),
        Pattern(
            "jp6", "～ます / ～ました — present / past", "～ます / ～ました — 「〜ます・〜ました」", "ja",
            "USAGE: ます is the polite present/future ending ('I do / will do'), ました is the polite past ('I did'). One of the most useful pairs in Japanese.\nWHEN: Use ます for habits and future plans: あさごはんをたべます (I eat breakfast / I will eat breakfast). Use ました for finished actions: きのうみました (I watched it yesterday).\nFORM: [verb stem] + ます / ました. Negative: ません / ませんでした.\nTIP: ます-form is the polite base form. To sound casual, use たべる / たべた. Many conjugations (たい, ましょう, て) build from the ます-stem.",
            "用途: ます は丁寧な現在・未来形（〜する／〜します）、ました は丁寧な過去形（〜した）です。とてもよく使うペアです。\nいつ: 習慣や予定には ます（あさごはんをたべます）。終わった動作には ました（きのうみました）。\n形: [動詞語幹] + ます / ました。否定: ません / ませんでした。\nヒント: ます形は丁寧の基本形。くだけた形は たべる / たべた。たい・ましょう などはすべてます形の語幹から作ります。",
            listOf(
                PatternExample("📚", "べんきょうします。", "benkyou shimasu", "I study / will study."),
                PatternExample("✅", "べんきょうしました。", "benkyou shimashita", "I studied.")
            ),
            "उपयोग: ます विनम्र वर्तमान/भविष्य ('करता हूँ'), ました विनम्र भूतकाल ('किया')। जापानी का सबसे उपयोगी जोड़ा।\nकब: आदतों/योजनाओं के लिए ます (あさごはんをたべます)। समाप्त कामों के लिए ました (きのうみました = कल देखा)।\nरूप: [क्रिया-तना] + ます / ました। नकारात्मक: ません / ませんでした।\nटिप: कैज़ुअल रूप है たべる/たべた। たい, ましょう आदि ます-तने से ही बनते हैं।"
        ),
        Pattern(
            "jp7", "～てください — polite request", "～てください — 「〜てください」", "ja",
            "USAGE: Attach てください to the te-form of a verb to make a polite request: 'please do ~'.\nWHEN: Use it for requests and instructions: まってください (Please wait), ここにすわってください (Please sit here). It is softer than a direct command.\nFORM: [verb te-form] + ください. Negative request: 〜ないでください (please don't ~).\nTIP: To make it even more polite, add ちょっと: ちょっとまってください (just a moment, please).",
            "用途: 動詞のて形に ください を付けて、丁寧な依頼「〜してください」を作ります。\nいつ: お願いや指示に使います。まってください、ここにすわってください。命令より柔らかい言い方です。\n形: [動詞て形] + ください。否定の依頼: 〜ないでください（〜しないでください）。\nヒント: さらに丁寧にするには ちょっと を足します。ちょっとまってください。",
            listOf(
                PatternExample("⏳", "まってください。", "matte kudasai", "Please wait."),
                PatternExample("🐢", "ゆっくりはなしてください。", "yukkuri hanashite kudasai", "Please speak slowly.")
            ),
            "उपयोग: क्रिया के te-रूप के साथ ください लगाकर विनम्र अनुरोध बनता है: 'कृपया ~ करें'।\nकब: अनुरोध और निर्देश के लिए: まってください (कृपया रुकें), ここにすわってください (कृपया यहाँ बैठें)। आदेश से नरम।\nरूप: [क्रिया का te-रूप] + ください। नकारात्मक अनुरोध: 〜ないでください।\nटिप: और विनम्र बनाने के लिए ちょっと जोड़ें: ちょっとまってください।"
        ),
        Pattern(
            "jp8", "～たいです — 'I want to ~'", "～たいです — 「〜たいです」", "ja",
            "USAGE: Change a verb to its ます-stem and add たいです to express what you want to do.\nWHEN: For desires and plans: にほんにいきたいです (I want to go to Japan), ねむいですからかえりたいです (I want to go home because I'm sleepy).\nFORM: [verb ます-stem] + たいです. Negative: たくないです. Past: たかったです.\nTIP: たい acts like an い-adjective, so it conjugates fully. For wanting a THING (not an action), use がほしいです instead.",
            "用途: 動詞のます形（語幹）に たいです を付けて「〜したい」という願望を表します。\nいつ: 願望や予定を言うとき。にほんにいきたいです、ねむいですからかえりたいです。\n形: [動詞ます語幹] + たいです。否定: たくないです。過去: たかったです。\nヒント: たい は い形容詞と同じように活用します。物が欲しいときは がほしいです を使います。",
            listOf(
                PatternExample("🇯🇵", "にほんにいきたいです。", "nihon ni ikitai desu", "I want to go to Japan."),
                PatternExample("🍜", "ラーメンをたべたいです。", "raamen wo tabetai desu", "I want to eat ramen.")
            ),
            "उपयोग: क्रिया के ます-तने में たいです जोड़कर इच्छा बताई जाती है: 'मैं ~ करना चाहता हूँ'।\nकब: इच्छा और योजनाओं के लिए: にほんにいきたいです (मैं जापान जाना चाहता हूँ), かえりたいです (मैं घर लौटना चाहता हूँ)।\nरूप: [क्रिया ます-तना] + たいです। नकारात्मक: たくないです। भूतकाल: たかったです।\nटिप: たい い-विशेषण जैसा है, पूरा रूप बदल सकते हैं। चीज़ चाहिए तो がほしいです।"
        ),
        Pattern(
            "jp9", "～に いきます — 'go to ~'", "～に いきます — 「〜に行きます」", "ja",
            "USAGE: The particle に (ni) marks the destination or goal of movement: the place you go to.\nWHEN: With verbs of movement: がっこうにいきます (I go to school), にほんにいきたいです (I want to go to Japan). Also used with かえる (return).\nFORM: [place] に [movement verb]. Common verbs: いきます (go), きます (come), かえります (return).\nTIP: に is for a destination you enter or reach. For movement 'through' a place, use を instead: こうえんをさんぽします (walk through the park).",
            "用途: 助詞 に は移動の目的地・行き先を示します。\nいつ: 行く・来る・帰る などの移動動詞と使います。がっこうにいきます、にほんにいきたいです。\n形: [場所] に [移動動詞]。よく使う動詞: いきます、きます、かえります。\nヒント: に は「到達する場所」に使います。通過する場所には を を使います（こうえんをさんぽします）。",
            listOf(
                PatternExample("🏫", "がっこうにいきます。", "gakkou ni ikimasu", "I go to school."),
                PatternExample("🚉", "えきにいきます。", "eki ni ikimasu", "I go to the station.")
            ),
            "उपयोग: कण に (ni) गंतव्य/लक्ष्य दिखाता है — जहाँ आप जाते हैं।\nकब: चलने-फिरने वाली क्रियाओं के साथ: がっこうにいきます (मैं स्कूल जाता हूँ), にほんにいきたいです (मैं जापान जाना चाहता हूँ)। साथ में かえる (लौटना)।\nरूप: [स्थान] に [गति-क्रिया]। सामान्य: いきます (जाना), きます (आना), かえります (लौटना)।\nटिप: に उस स्थान के लिए जहाँ पहुँचते हैं; रास्ते में होकर जाने के लिए を (こうえんをさんぽします)।"
        ),
        Pattern(
            "jp10", "あります / います — existence", "あります / います — 「あります・います」", "ja",
            "USAGE: あります means 'there is' for non-living things (books, trees, shops); います means 'there is' for living things (people, animals).\nWHEN: For location and existence: つくえのうえにほんがあります (There is a book on the desk), こうえんにこどもがいます (There is a child in the park).\nFORM: [place] に [thing] が あります / います. Negative: ありません / いません.\nTIP: あります never takes a living subject — ねこがあります would be wrong; the correct form is ねこがいます.",
            "用途: あります はモノ（本・木・店）の存在、います は人や動物の存在を表します。\nいつ: 場所の説明に使います。つくえのうえにほんがあります、こうえんにこどもがいます。\n形: [場所] に [もの] が あります / います。否定: ありません / いません。\nヒント: あります に生き物は使えません。ねこがあります は間違いで、ねこがいます が正しいです。",
            listOf(
                PatternExample("📖", "ほんがあります。", "hon ga arimasu", "There is a book."),
                PatternExample("🐶", "いぬがいます。", "inu ga imasu", "There is a dog.")
            ),
            "उपयोग: あります निर्जीव चीज़ों (किताब, पेड़, दुकान) के लिए 'है', います जीवित प्राणियों (लोग, जानवर) के लिए 'है'।\nकब: स्थान बताने के लिए: つくえのうえにほんがあります (मेज़ पर किताब है), こうえんにこどもがいます (पार्क में बच्चा है)।\nरूप: [स्थान] に [चीज़] が あります / います। नकारात्मक: ありません / いません।\nटिप: あります के साथ जीवित प्राणी नहीं। सही है ねこがいます, ग़लत है ねこがあります।"
        ),
        Pattern(
            "jp11", "～から ～まで — 'from ~ to ~'", "～から ～まで — 「〜から〜まで」", "ja",
            "USAGE: から = 'from' (starting point), まで = 'to / until' (end point). Used for both time and places.\nWHEN: Time: くじからごじまで (from 9 to 5). Places: とうきょうからおおさかまで (from Tokyo to Osaka).\nFORM: [start] から [end] まで + verb: くじからごじまではたらきます = I work from 9 to 5.\nTIP: You can use either one alone: あしたまで = until tomorrow, にほんから = from Japan.",
            "用途: から は起点（〜から）、まで は終点（〜まで）を示します。時間にも場所にも使えます。\nいつ: 時間の範囲（くじからごじまで）、場所の範囲（とうきょうからおおさかまで）を言うとき。\n形: [起点] から [終点] まで。後ろに動詞を続けます。くじからごじまではたらきます。\nヒント: 片方だけでも使えます。あしたまで = 明日まで、にほんから = 日本から。",
            listOf(
                PatternExample("💼", "あさからばんまではたらきます。", "asa kara ban made hatarakimasu", "I work from morning to night."),
                PatternExample("🕘", "くじからごじまで。", "kuji kara goji made", "From 9 to 5.")
            ),
            "उपयोग: から = 'से' (आरंभ), まで = 'तक' (अंत)। समय और स्थान दोनों के लिए।\nकब: समय सीमा (くじからごじまで = 9 से 5 तक), स्थान सीमा (とうきょうからおおさかまで = टोक्यो से ओसाका तक)।\nरूप: [आरंभ] から [अंत] まで + क्रिया: くじからごじまではたらきます।\nटिप: अकेले भी चलते हैं: あしたまで = कल तक, にほんから = जापान से।"
        ),
        Pattern(
            "jp12", "こ・そ・あ — this / that", "こ・そ・あ — 「こそあど」", "ja",
            "USAGE: これ = this (near me), それ = that (near you), あれ = that over there (away from both). These are the ko-so-a words.\nWHEN: Pointing at things: これはなんですか (What is this?), それはほんです (That is a book). Before a noun use この/その/あの: このほん (this book).\nFORM: これ / それ / あれ は [thing] です. With nouns: この / その / あの + [noun].\nTIP: The same ko-so-a pattern extends to places (ここ/そこ/あそこ), people (このひと) and directions (こっち/そっち/あっち).",
            "用途: これ=私の近くのもの、それ=あなたの近くのもの、あれ=両方から遠いもの。こそあど言葉です。\nいつ: 物を指さして言うとき。これはなんですか、それはほんです。名詞を修飾するときは この・その・あの + 名詞。\n形: これ / それ / あれ は [もの] です。名詞と: この / その / あの + [名詞]。\nヒント: 同じこそあどは場所（ここ/そこ/あそこ）、人（このひと）、方向（こっち/そっち/あっち）にも広がります。",
            listOf(
                PatternExample("📖", "これはほんです。", "kore wa hon desu", "This is a book."),
                PatternExample("✏️", "それはえんぴつです。", "sore wa enpitsu desu", "That is a pencil."),
                PatternExample("🚗", "あれはくるまです。", "are wa kuruma desu", "That over there is a car.")
            ),
            "उपयोग: これ = यह (मेरे पास), それ = वह (तुम्हारे पास), あれ = वह दूर (दोनों से)। ko-so-a शब्द।\nकब: चीज़ की ओर इशारा करते हुए: これはなんですか (यह क्या है?), それはほんです (वह किताब है)। संज्ञा के साथ: このほん (यह किताब)।\nरूप: これ/それ/あれ は [चीज़] です। संज्ञा के साथ: この/その/あの + [संज्ञा]।\nटिप: यही पैटर्न जगह (ここ/そこ/あそこ), लोगों (このひと) और दिशाओं (こっち/そっち/あっち) पर लागू होता है।"
        ),
        Pattern(
            "jp13", "～ています — doing right now", "～ています — 「〜ています」", "ja",
            "USAGE: Te-form + います = an action in progress ('is doing') or a continuing state.\nWHEN: Current actions: ほんをよんでいます (I am reading a book). Continuing states: とうきょうにすんでいます (I live in Tokyo), けっこんしています (I am married).\nFORM: [verb te-form] + います. Past: 〜ていました. Negative: 〜ていません.\nTIP: It also works for habits: まいにちうんどうしています = I exercise every day. Don't confuse it with simple ます, which is a general statement.",
            "用途: て形 + います で「動作の進行中」や「継続している状態」を表します。\nいつ: いましている動作（ほんをよんでいます）、続いている状態（とうきょうにすんでいます、けっこんしています）。\n形: [動詞て形] + います。過去: 〜ていました。否定: 〜ていません。\nヒント: 習慣にも使えます。まいにちうんどうしています。単なる ます とは違うので注意。",
            listOf(
                PatternExample("📚", "べんきょうしています。", "benkyou shite imasu", "I'm studying (right now)."),
                PatternExample("📺", "テレビをみています。", "terebi wo mite imasu", "I'm watching TV.")
            ),
            "उपयोग: te-रूप + います = चल रही क्रिया ('कर रहा हूँ') या जारी स्थिति।\nकब: अभी चल रहे काम (ほんをよんでいます = मैं किताब पढ़ रहा हूँ), जारी स्थिति (とうきょうにすんでいます = मैं टोक्यो में रहता हूँ), (けっこんしています = मैं विवाहित हूँ)।\nरूप: [क्रिया te-रूप] + います। भूतकाल: 〜ていました। नकारात्मक: 〜ていません।\nटिप: आदतों के लिए भी: まいにちうんどうしています। साधारण ます से अलग है।"
        ),
        Pattern(
            "jp14", "い-adj / な-adj — two kinds of adjectives", "い形容詞・な形容詞", "ja",
            "USAGE: Japanese has two adjective types. い-adjectives end in い (おいしい, かわいい, たかい). な-adjectives don't and take な before a noun (きれいな, ゆうめいな).\nWHEN: Before nouns: おいしいりょうり (delicious food), きれいなはな (pretty flower). い-adjectives conjugate by themselves (たかい → たかくないです); な-adjectives use です / じゃないです.\nFORM: [い-adj] + noun | [な-adj] な + noun. Present negative い-adj: 〜くないです. Present negative な-adj: じゃないです.\nTIP: Some words end in い but are な-adjectives (きれい, ゆうめい). Test by checking whether な works before the noun.",
            "用途: 日本語の形容詞には2種類あります。い形容詞は「い」で終わり、な形容詞は名詞の前に な を付けます（きれいな、ゆうめいな）。\nいつ: 名詞の前で使います。おいしいりょうり、きれいなはな。い形容詞は自分で活用します（たかい→たかくないです）。な形容詞は です/じゃないです を使います。\n形: [い形容詞] + 名詞 | [な形容詞] な + 名詞。い形容詞の否定: 〜くないです。な形容詞の否定: じゃないです。\nヒント: きれい や ゆうめい は「い」で終わりますが な形容詞です。名詞の前に な が付くかどうかで判断しましょう。",
            listOf(
                PatternExample("😋", "おいしいです。", "oishii desu", "It's delicious."),
                PatternExample("🌸", "きれいなはなです。", "kirei na hana desu", "It's a pretty flower.")
            ),
            "उपयोग: जापानी में दो तरह के विशेषण। い-विशेषण 'い' से ख़त्म होते हैं (おいしい, たかい); な-विशेषण संज्ञा से पहले な लेते हैं (きれいな, ゆうめいな)।\nकब: संज्ञा से पहले: おいしいりょうり (स्वादिष्ट खाना), きれいなはな (सुंदर फूल)। い-विशेषण खुद बदलते हैं (たかい→たかくない); な-विशेषण です/じゃないです से।\nरूप: [い-विशेषण] + संज्ञा | [な-विशेषण] な + संज्ञा।\nटिप: きれい, ゆうめい 'い' से ख़त्म होते हुए भी な-विशेषण हैं — संज्ञा से पहले な लगाकर जाँचें।"
        ),
        Pattern(
            "en1", "am / is / are — the verb 'be'", "am / is / are — be動詞", "en",
            "USAGE: 'be' is the most important verb in English. It links a person or thing to a description: I am, you are, he/she/it is, we/they are.\nWHEN: For identity, description and state: I am a student, She is happy, They are my friends. Also for age and where you're from.\nFORM: I am | you/we/they are | he/she/it is. Contractions: I'm, you're, she's. Negative: am not, isn't, aren't.\nTIP: English always needs a verb — you can't say 'I student'. Contracted forms (I'm, it's) are the norm in speech and informal writing.",
            "用途: be動詞は英語で最も重要な動詞です。人や物を説明に結び付けます。I am（私）、you are（あなた）、he/she is（彼・彼女）、we/they are。\nいつ: 身分・状態・説明に使います。I am a student、She is happy、They are my friends。年齢や出身地にも使います。\n形: I am | you/we/they are | he/she/it is。短縮形: I'm、you're、she's。否定: am not / isn't / aren't。\nヒント: 英語は必ず動詞が必要です。「I student」は言えません。会話では短縮形（I'm、it's）が普通です。",
            listOf(
                PatternExample("🎓", "I am a student.", "アイ アム ア スチューデント", "わたしはがくせいです。"),
                PatternExample("💖", "You are kind.", "ユー アー カインド", "あなたはやさしいです。"),
                PatternExample("👩", "She is a teacher.", "シー イズ ア ティーチャー", "かのじょはせんせいです。")
            ),
            "उपयोग: 'be' अंग्रेज़ी की सबसे महत्वपूर्ण क्रिया है — व्यक्ति/वस्तु को विवरण से जोड़ती है: I am, you are, he/she/it is, we/they are।\nकब: पहचान, वर्णन और अवस्था के लिए: I am a student (मैं विद्यार्थी हूँ), She is happy (वह खुश है), They are my friends। उम्र और गृह-नगर के लिए भी।\nरूप: I am | you/we/they are | he/she/it is। संक्षिप्त: I'm, you're, she's। नकारात्मक: am not, isn't, aren't।\nटिप: अंग्रेज़ी में क्रिया ज़रूरी है — 'I student' नहीं चलता। बोलचाल में I'm, it's चलता है।"
        ),
        Pattern(
            "en2", "a / an / the — articles", "a / an / the — 冠詞", "en",
            "USAGE: a/an = one (general, not specific). Use 'an' before a vowel SOUND (an apple, an hour). the = a specific one the listener knows about.\nWHEN: a/an for first mention: I saw a cat. the for second mention or shared knowledge: The cat was black. the also for unique things: the sun, the moon.\nFORM: a + consonant sound (a book), an + vowel sound (an egg), the + any noun (the book).\nTIP: 'an' depends on sound, not spelling: an hour (h is silent), a university (starts with 'yoo'). Japanese has no articles, so this takes practice.",
            "用途: a/an は「1つの〜」（不特定）、the は「その〜」（特定・既知）です。母音の音の前では an。\nいつ: 初めて出てくる物には a/an、話し手と聞き手が知っている物には the。the sun、the moon のような唯一のものにも the。\n形: a + 子音（a book）、an + 母音の音（an egg）、the + 名詞（the book）。\nヒント: 大事なのは綴りではなく音です（an hour、a university）。日本語に冠詞はないので練習が必要です。",
            listOf(
                PatternExample("🐱", "I have a cat.", "アイ ハヴ ア キャット", "ねこをかっています。"),
                PatternExample("🍎", "Give me an apple.", "ギヴ ミー アン アップル", "りんごをください。"),
                PatternExample("☀️", "The sun is bright.", "ザ サン イズ ブライト", "たいようはあかるいです。")
            ),
            "उपयोग: a/an = एक (सामान्य, अनिश्चित), the = वही विशेष (निश्चित)। स्वर-ध्वनि से पहले an।\nकब: पहली बार ज़िक्र पर a/an (I saw a cat — मैंने बिल्ली देखी), फिर the (The cat was black)। अनोखी चीज़ों पर the: the sun, the moon।\nरूप: a + व्यंजन-ध्वनि (a book), an + स्वर-ध्वनि (an egg), the + कोई भी संज्ञा।\nटिप: अहम ध्वनि है, वर्तनी नहीं: an hour (h मौन), a university ('यू' ध्वनि)। जापानी में articles नहीं हैं, अभ्यास चाहिए।"
        ),
        Pattern(
            "en3", "-s plural — more than one", "-s 複数形", "en",
            "USAGE: Add -s to most nouns to make them plural: one book → two books.\nWHEN: Counting and general statements about multiple things: three dogs, I like cats.\nFORM: noun + s (books, cats) | es after s/sh/ch/x (boxes, watches) | y→ies (city→cities) | irregulars (child→children, man→men, foot→feet).\nTIP: Common irregular plurals must be memorized: person→people, woman→women, tooth→teeth, sheep→sheep (no change). Don't add -s to uncountable nouns: water, money, information.",
            "用途: 名詞の複数形は普通 -s を付けます。one book → two books。\nいつ: 数えたり、複数のものについて言うとき。three dogs、I like cats。\n形: 名詞 + s（books、cats）| s/sh/ch/x の後は es（boxes、watches）| y→ies（city→cities）| 不規則（child→children、man→men、foot→feet）。\nヒント: person→people、sheep→sheep など不規則なものは覚えましょう。water や money のような不加算名詞には -s を付けません。",
            listOf(
                PatternExample("📚", "one book, two books", "ワン ブック トゥー ブックス", "いっさつ、にさつ"),
                PatternExample("🐱", "three cats", "スリー キャッツ", "さんびきのねこ"),
                PatternExample("🧒", "five children", "ファイヴ チルドレン", "ごにんのこども")
            ),
            "उपयोग: अधिकांश संज्ञाओं को बहुवचन बनाने के लिए -s लगाते हैं: one book → two books।\nकब: गिनती और कई चीज़ों की बात में: three dogs, I like cats।\nरूप: संज्ञा + s | s/sh/ch/x के बाद es (boxes, watches) | y→ies (city→cities) | अनियमित (child→children, man→men, foot→feet)।\nटिप: person→people, sheep→sheep जैसे अनियमित रूप याद करें। water, money जैसी अगणनीय संज्ञाओं में -s नहीं।"
        ),
        Pattern(
            "en4", "-ing — doing right now", "-ing 現在進行形", "en",
            "USAGE: am/is/are + verb-ing = an action happening right now: I am reading.\nWHEN: For actions in progress now: She is cooking dinner. Also for temporary situations: I am living in Tokyo this year.\nFORM: be (am/is/are) + verb-ing. Spelling: read→reading, run→running (double consonant), make→making (drop e), lie→lying (ie→y).\nTIP: Don't use it for permanent states — 'I am liking' is wrong; say I like. Use -ing only for actions happening around now.",
            "用途: be動詞 + 動詞のing形 で「今していること」を表します。I am reading。\nいつ: 進行中の動作（She is cooking dinner）、一時的な状況（I am living in Tokyo this year）。\n形: be（am/is/are）+ 動詞ing。綴りの注意: run→running（子音を重ねる）、make→making（eを落とす）。\nヒント: 恒常的な状態には使いません。「I am liking」は間違いで、I like が正しいです。",
            listOf(
                PatternExample("📖", "I am reading.", "アイ アム リーディング", "よんでいます。"),
                PatternExample("😴", "She is sleeping.", "シー イズ スリーピング", "かのじょはねています。")
            ),
            "उपयोग: am/is/are + क्रिया-ing = अभी चल रही क्रिया: I am reading (मैं पढ़ रहा हूँ)।\nकब: अभी चल रहे काम (She is cooking dinner), अस्थायी स्थिति (I am living in Tokyo this year)।\nरूप: be (am/is/are) + क्रिया-ing। वर्तनी: run→running (व्यंजन दुगना), make→making (e हटाएँ), lie→lying।\nटिप: स्थायी बातों के लिए नहीं — 'I am liking' ग़लत है; सही I like।"
        ),
        Pattern(
            "en5", "-ed — simple past", "-ed 過去形", "en",
            "USAGE: Add -ed to make the simple past: walk → walked, I walked to school.\nWHEN: Finished actions in the past with a definite time: I watched a movie yesterday, We lived in Osaka in 2019.\nFORM: verb + ed (walked, played) | y→ied (study→studied) | e + d (live→lived) | irregulars (go→went, eat→ate, see→saw, have→had).\nTIP: Irregular verbs are very common — make a list and drill them. The past form is the same for all persons: I went, she went.",
            "用途: 過去形は普通 -ed を付けます。walk → walked。\nいつ: 明確な時間のある終わった動作。I watched a movie yesterday、We lived in Osaka in 2019。\n形: 動詞 + ed | y→ied（study→studied）| e + d（live→lived）| 不規則（go→went、eat→ate、see→saw）。\nヒント: 不規則動詞はとてもよく使うので、リストを作って練習しましょう。過去形は人称に関係なく同じです（I went、she went）。",
            listOf(
                PatternExample("🚶", "I walked to school.", "アイ ウォークト トゥー スクール", "がっこうまであるきました。"),
                PatternExample("📚", "She studied English.", "シー スタディド イングリッシュ", "かのじょはえいごをべんきょうしました。"),
                PatternExample("🏠", "We went home.", "ウィー ウェント ホーム", "うちにかえりました。")
            ),
            "उपयोग: सामान्य भूतकाल के लिए -ed जोड़ते हैं: walk → walked।\nकब: निश्चित समय वाले समाप्त काम: I watched a movie yesterday (मैंने कल फ़िल्म देखी), We lived in Osaka in 2019।\nरूप: क्रिया + ed | y→ied (study→studied) | e + d (live→lived) | अनियमित (go→went, eat→ate, see→saw)।\nटिप: अनियमित क्रियाएँ बहुत आम हैं — सूची बनाकर याद करें। भूतकाल सभी पुरुषों के लिए एक जैसा: I went, she went।"
        ),
        Pattern(
            "en6", "do / does — asking questions", "do / does 疑問文", "en",
            "USAGE: Start a yes/no question with do (I/you/we/they) or does (he/she/it) for present simple verbs.\nWHEN: Asking about habits and facts: Do you like coffee? Does she play tennis? What do you do on weekends?\nFORM: Do/Does + subject + base verb: Does he work? Note the verb stays base (does he work, not does he works).\nTIP: When you use does, the main verb drops its -s: She works → Does she work? Short answers: Yes, I do / No, she doesn't.",
            "用途: 現在形の疑問文は do（I/you/we/they）か does（he/she/it）で始めます。\nいつ: 習慣や事実を聞くとき。Do you like coffee?、Does she play tennis?\n形: Do/Does + 主語 + 動詞の原形。Does he work? のようになり、動詞は原形のままです（does he works は間違い）。\nヒント: does を使うとき、動詞の -s は消えます。She works → Does she work? 短い答え: Yes, I do / No, she doesn't。",
            listOf(
                PatternExample("☕", "Do you like coffee?", "ドゥ ユー ライク コーヒー", "コーヒーはすきですか。"),
                PatternExample("⚽", "Does he play soccer?", "ダズ ヒー プレイ サッカー", "かれはサッカーをしますか。")
            ),
            "उपयोग: हाँ/नहीं वाले प्रश्न do (I/you/we/they) या does (he/she/it) से शुरू होते हैं।\nकब: आदतों और तथ्यों के बारे में: Do you like coffee? Does she play tennis?\nरूप: Do/Does + कर्ता + मूल क्रिया: Does he work? (does he works ग़लत)।\nटिप: does के साथ मुख्य क्रिया से -s हटता है: She works → Does she work? छोटा उत्तर: Yes, I do / No, she doesn't।"
        ),
        Pattern(
            "en7", "going to — future plans", "going to 未来形", "en",
            "USAGE: am/is/are + going to + verb = a future plan or intention.\nWHEN: Decided plans and predictions based on evidence: I am going to study tonight, It is going to rain (look at those clouds).\nFORM: be + going to + base verb: She is going to visit her grandmother. Negative: am not going to / isn't going to.\nTIP: For instant decisions at the moment of speaking, use will (I'll take it!) — for pre-made plans, use going to. The key difference is how planned it is.",
            "用途: be動詞 + going to + 動詞の原形 で未来の予定・意図を表します。\nいつ: 決まっている予定（I am going to study tonight）、根拠のある予測（It is going to rain）。\n形: be + going to + 動詞の原形。She is going to visit her grandmother。否定: am not going to / isn't going to。\nヒント: その場での決断には will（I'll take it!）、あらかじめ決めた予定には going to。計画があるかどうかがポイントです。",
            listOf(
                PatternExample("📚", "I am going to study.", "アイ アム ゴーイング トゥー スタディ", "べんきょうするつもりです。"),
                PatternExample("✈️", "She is going to travel.", "シー イズ ゴーイング トゥー トラベル", "かのじょはりょこうします。")
            ),
            "उपयोग: am/is/are + going to + क्रिया = भविष्य की योजना या इरादा।\nकब: तय योजनाएँ और संकेतों पर आधारित भविष्यवाणी: I am going to study tonight (आज रात पढ़ूँगा), It is going to rain (बारिश होने वाली है)।\nरूप: be + going to + मूल क्रिया: She is going to visit her grandmother। नकारात्मक: am not going to / isn't going to।\nटिप: पल भर का फ़ैसला = will, पहले से तय योजना = going to। फ़र्क योजना की पक्कीपन में।"
        ),
        Pattern(
            "en8", "can / can't — ability", "can / can't 可能", "en",
            "USAGE: can = able to do; can't = not able to. The form never changes: I can, she can.\nWHEN: Abilities and skills: I can swim, She can speak three languages. Permission: Can I use your phone? Requests: Can you help me?\nFORM: can/can't + base verb: He can run fast. Negative: cannot / can't. Question: Can you ~?\nTIP: can is a modal verb — no -s for he/she, no do/does in questions. 'Can I ~?' is a common polite way to ask permission.",
            "用途: can は「〜できる」、can't は「〜できない」。形は主語に関係なく同じです（I can、she can）。\nいつ: 能力・技能（I can swim）、許可（Can I use your phone?）、依頼（Can you help me?）。\n形: can/can't + 動詞の原形。He can run fast。否定: cannot / can't。疑問: Can you ~?\nヒント: can は助動詞なので he/she でも -s を付けず、疑問文も do を使いません。「Can I ~?」は丁寧な許可の求め方です。",
            listOf(
                PatternExample("🏊", "I can swim.", "アイ キャン スイム", "およげます。"),
                PatternExample("🚗", "He can't drive.", "ヒー キャント ドライヴ", "かれはうんてんできません。")
            ),
            "उपयोग: can = 'कर सकता हूँ', can't = 'नहीं कर सकता'। रूप कभी नहीं बदलता: I can, she can।\nकब: क्षमता (I can swim — मैं तैर सकता हूँ), अनुमति (Can I use your phone?), अनुरोध (Can you help me?)।\nरूप: can/can't + मूल क्रिया: He can run fast। नकारात्मक: cannot/can't। प्रश्न: Can you ~?\nटिप: can modal क्रिया है — he/she के साथ -s नहीं, प्रश्न में do नहीं। 'Can I ~?' विनम्र अनुमति के लिए।"
        ),
        Pattern(
            "en9", "there is / there are — existence", "there is / there are — 存在", "en",
            "USAGE: there is + singular, there are + plural: 'There is a book on the table.'\nWHEN: Saying that something exists somewhere: There is a park near my house, There are many restaurants in this city.\nFORM: There is + singular noun / There are + plural noun + place. Negative: there isn't / there aren't. Question: Is there ~? / Are there ~?\nTIP: Don't translate word-for-word — 'there' here doesn't mean a place; it just introduces the sentence. Short answer: Is there a bank? Yes, there is.",
            "用途: 単数には there is、複数には there are を使います。There is a book on the table。\nいつ: 何かがどこかに存在すると言うとき。There is a park near my house、There are many restaurants in this city。\n形: There is + 単数名詞 / There are + 複数名詞 + 場所。否定: there isn't / there aren't。疑問: Is there ~? / Are there ~?\nヒント: ここでの there は場所ではなく、文を始めるための言葉です。Is there a bank? → Yes, there is。",
            listOf(
                PatternExample("📖", "There is a book on the table.", "ゼア イズ ア ブック オン ザ テーブル", "テーブルのうえにほんがあります。"),
                PatternExample("🐱", "There are three cats.", "ゼア アー スリー キャッツ", "ねこがさんびきいます。")
            ),
            "उपयोग: एकवचन के साथ there is, बहुवचन के साथ there are: 'There is a book on the table' (मेज़ पर किताब है)।\nकब: कहीं किसी चीज़ के होने की बात: There is a park near my house, There are many restaurants in this city।\nरूप: There is + एकवचन / There are + बहुवचन + स्थान। नकारात्मक: there isn't/there aren't। प्रश्न: Is there ~? / Are there ~?\nटिप: यहाँ there जगह नहीं — सिर्फ वाक्य शुरू करने के लिए। Is there a bank? → Yes, there is।"
        ),
        Pattern(
            "en10", "in / on / at — prepositions of place & time", "in / on / at 前置詞", "en",
            "USAGE: in = inside a large area (in the box, in the morning, in July). on = on top of / a surface (on the table, on Monday). at = a specific point (at 3 o'clock, at the station).\nWHEN: Place: in the kitchen, on the wall, at the bus stop. Time: in the morning, on Sunday, at night.\nFORM: in + month/year/period | on + day/date | at + clock time/point.\nTIP: The classic order: in (big periods: months, years) → on (days, dates) → at (exact times). 'At night' and 'in the morning' are fixed exceptions — memorize them.",
            "用途: in=広い範囲・期間の中（in the box、in July）、on=表面の上（on the table、on Monday）、at=特定の一点（at 3 o'clock、at the station）。\nいつ: 場所: in the kitchen、on the wall、at the bus stop。時間: in the morning、on Sunday、at night。\n形: in + 月・年・期間 | on + 曜日・日付 | at + 時刻・地点。\nヒント: 時間は in（月・年）→ on（曜日・日付）→ at（時刻）の順。at night と in the morning は例外として覚えましょう。",
            listOf(
                PatternExample("📦", "It's in the box.", "イッツ イン ザ ボックス", "はこのなかにあります。"),
                PatternExample("🪑", "It's on the table.", "イッツ オン ザ テーブル", "テーブルのうえにあります。"),
                PatternExample("🕒", "At 3 o'clock.", "アット スリー オクロック", "さんじに。")
            ),
            "उपयोग: in = बड़े क्षेत्र/अवधि के अंदर (in the box, in July), on = सतह पर (on the table, on Monday), at = एक बिंदु पर (at 3 o'clock, at the station)।\nकब: स्थान: in the kitchen, on the wall, at the bus stop। समय: in the morning, on Sunday, at night।\nरूप: in + महीना/साल | on + दिन/तारीख़ | at + ठीक समय/बिंदु।\nटिप: क्रम: in (बड़ी अवधि) → on (दिन) → at (ठीक समय)। at night और in the morning अपवाद हैं — याद करें।"
        ),
        Pattern(
            "en11", "comparatives — -er / more", "比較級 -er / more", "en",
            "USAGE: Short words take -er (big → bigger, fast → faster); long words take more (beautiful → more beautiful). Compare two things with 'than'.\nWHEN: Comparing two things: This phone is cheaper than that one, She is more careful than her brother.\nFORM: short adj + er + than | more + long adj + than. Spelling: big→bigger (double consonant), easy→easier (y→ier). Irregular: good→better, bad→worse, far→farther.\nTIP: One-syllable and many two-syllable words use -er; words with 3+ syllables use more. Use 'than' to name the other thing.",
            "用途: 短い形容詞は -er（big→bigger）、長い形容詞は more（more beautiful）を付けます。比較には than を使います。\nいつ: 二つのものを比べるとき。This phone is cheaper than that one、She is more careful than her brother。\n形: 短い形容詞 + er + than | more + 長い形容詞 + than。綴り: big→bigger（子音を重ねる）、easy→easier（y→ier）。不規則: good→better、bad→worse。\nヒント: 1音節・2音節の多くは -er、3音節以上は more。比較の相手は than で示します。",
            listOf(
                PatternExample("🐘", "A cat is smaller than a dog.", "ア キャット イズ スモーラー ザン ア ドッグ", "ねこはいぬよりちいさいです。"),
                PatternExample("🌸", "This flower is more beautiful.", "ジス フラワー イズ モア ビューティフル", "このはなはもっときれいです。")
            ),
            "उपयोग: छोटे शब्दों में -er (big→bigger), लंबे शब्दों में more (more beautiful)। तुलना में than लगता है।\nकब: दो चीज़ों की तुलना: This phone is cheaper than that one (यह फ़ोन उससे सस्ता है), She is more careful than her brother।\nरूप: छोटा विशेषण + er + than | more + लंबा विशेषण + than। वर्तनी: big→bigger (व्यंजन दुगना), easy→easier। अनियमित: good→better, bad→worse।\nटिप: 1-2 अक्षरों में -er, 3+ अक्षरों में more। दूसरी चीज़ than से जोड़ें।"
        ),
        Pattern(
            "en12", "have / has — possession", "have / has 所有", "en",
            "USAGE: have = I/you/we/they have; has = he/she/it has. Shows possession and some states.\nWHEN: Possession: I have a car, She has two brothers. States: I have a question, He has a cold.\nFORM: have/has + noun. Negative: don't have / doesn't have. Question: Do you have ~? / Does she have ~?\nTIP: Common contraction: I've got = I have (more British). For the past, use had for everyone: I had a dog.",
            "用途: 所有を表します。I/you/we/they には have、he/she/it には has。\nいつ: 所有（I have a car、She has two brothers）、状態（I have a question、He has a cold）。\n形: have/has + 名詞。否定: don't have / doesn't have。疑問: Do you have ~? / Does she have ~?\nヒント: I've got = I have（イギリス英語で多い）。過去形は全員 had です。I had a dog。",
            listOf(
                PatternExample("📱", "I have a phone.", "アイ ハヴ ア フォン", "けいたいをもっています。"),
                PatternExample("🐶", "She has two dogs.", "シー ハズ トゥー ドッグズ", "かのじょはいぬをにひきかっています。")
            ),
            "उपयोग: possession के लिए — I/you/we/they के साथ have, he/she/it के साथ has।\nकब: स्वामित्व: I have a car (मेरे पास कार है), She has two brothers। अवस्था: I have a question, He has a cold।\nरूप: have/has + संज्ञा। नकारात्मक: don't have / doesn't have। प्रश्न: Do you have ~? / Does she have ~?\nटिप: I've got = I have (ब्रिटिश अंग्रेज़ी)। भूतकाल सबके लिए had: I had a dog।"
        ),
        Pattern(
            "jp15", "も — 'also / too'", "〜も — 「も」", "ja",
            "USAGE: も (mo) means 'also' or 'too'. Swap は for も to add extra information about another thing or person.\nWHEN: When the same statement applies to someone/something else: コーヒーものみます (I drink coffee too), わたしもです (Me too). Also for emphasis with numbers: にじゅうにんも (as many as 20 people).\nFORM: [noun] も [rest of sentence]. It replaces は and が but combines with other particles: にほんにもいきました (I also went to Japan).\nTIP: も replaces は/が, but after に, で, へ, から the particle stays and も is added. In negative sentences it means 'either': わたしもいきません = I'm not going either.",
            "用途: も は「〜も（also / too）」の意味で、は の代わりに使います。\nいつ: 同じことが他のものにも当てはまるとき。コーヒーものみます、わたしもです。数の強調（にじゅうにんも）にも使います。\n形: [名詞] も [文]。は・が を置き換えますが、に・で・から とは併用します（にほんにもいきました）。\nヒント: は・が は も に置き換え、に・で・から には も を付け足します。否定文では「〜も〜ない（either）」になります。",
            listOf(
                PatternExample("☕", "コーヒーものみます。", "koohii mo nomimasu", "I drink coffee too.", "मैं भी कॉफ़ी पीता हूँ।"),
                PatternExample("🍎", "りんごもたべます。", "ringo mo tabemasu", "I also eat apples.", "मैं सेब भी खाता हूँ।")
            ),
            "उपयोग: も (mo) का अर्थ 'भी' है। は की जगह も लगाकर अतिरिक्त जानकारी जोड़ते हैं।\nकब: जब बात किसी और पर भी लागू हो: コーヒーものみます (मैं कॉफ़ी भी पीता हूँ), わたしもです (मैं भी)। संख्याओं के साथ ज़ोर के लिए: にじゅうにんも (पूरे 20 लोग)।\nरूप: [संज्ञा] も [शेष वाक्य]। यह は/が की जगह लेता है, पर に・で・から के साथ जुड़ता है: にほんにもいきました।\nटिप: は/ग की जगह लेता है, बाकी कणों के बाद जुड़ता है। नकारात्मक में 'भी नहीं': わたしもいきません।"
        ),
        Pattern(
            "jp16", "〜ましょう — 'let's ~'", "〜ましょう — 「〜ましょう」", "ja",
            "USAGE: Change ます to ましょう to suggest doing something together or to express intention.\nWHEN: Proposals: いっしょにたべましょう (Let's eat together). Offers of help: てつだいましょうか (Shall I help you?). Polite intention: わたしがいきましょう (I'll go).\nFORM: [verb ます-stem] + ましょう. Soft question form: 〜ましょうか (shall we ~?).\nTIP: 〜ましょうか can mean both 'let's ~' and 'shall I ~?' — context decides. The casual equivalent is 〜よう (たべよう).",
            "用途: ます を ましょう に変えて、一緒に何かをする提案や意志を表します。\nいつ: 誘い（いっしょにたべましょう）、手伝いの申し出（てつだいましょうか）、意志（わたしがいきましょう）。\n形: [動詞ます語幹] + ましょう。やわらかい疑問: 〜ましょうか。\nヒント: ましょうか は「一緒に〜しませんか」と「〜しましょうか」の両方に使えます。くだけた形は 〜よう（たべよう）。",
            listOf(
                PatternExample("🍜", "たべましょう。", "tabemashou", "Let's eat.", "चलो खाते हैं।"),
                PatternExample("📚", "べんきょうしましょう。", "benkyou shimashou", "Let's study.", "चलो पढ़ाई करते हैं।")
            ),
            "उपयोग: ます को ましょう में बदलकर साथ में करने का प्रस्ताव या इरादा ज़ाहिर करते हैं।\nकब: प्रस्ताव (いっしょにたべましょう = चलो साथ खाएँ), मदद की पेशकश (てつだいましょうか = क्या मैं मदद करूँ?), इरादा (わたしがいきましょう = मैं जाऊँगा)।\nरूप: [क्रिया ます-तना] + ましょう। नरम सवाल: 〜ましょうか।\nटिप: ましょうか से 'चलो ~ करें' और 'क्या मैं ~ करूँ?' दोनों बनते हैं। कैज़ुअल: 〜よう (たべよう)।"
        ),
        Pattern(
            "jp17", "〜てもいいです — 'may I / you can ~'", "〜てもいいです — 「〜てもいいです」", "ja",
            "USAGE: Te-form + もいいです gives or asks for permission: 'may / you can ~'.\nWHEN: Asking permission: はいってもいいですか (May I come in?), しゃしんをとってもいいですか (May I take a photo?). Giving permission: いいですよ / どうぞ (Go ahead).\nFORM: [verb te-form] + もいいです. Question: 〜てもいいですか. Not allowed: 〜てはいけません.\nTIP: てはいけません is the opposite — 'must not'. With friends, a bare いい? works: たべていい? (Can I eat?).",
            "用途: て形 + もいいです で許可を表します。「〜してもいい（です）」。「〜してもよい」とも書きます。\nいつ: 許可を求めるとき（はいってもいいですか）、許可を与えるとき（いいですよ）。\n形: [動詞て形] + もいいです。疑問: 〜てもいいですか。禁止: 〜てはいけません。\nヒント: てはいけません は反対の「〜してはいけない」。友達には いい? だけでも通じます。",
            listOf(
                PatternExample("🚪", "はいってもいいですか。", "haitte mo ii desu ka", "May I come in?", "क्या मैं अंदर आ सकता हूँ?"),
                PatternExample("📷", "しゃしんをとってもいいですか。", "shashin wo totte mo ii desu ka", "May I take a photo?", "क्या मैं फ़ोटो ले सकता हूँ?")
            ),
            "उपयोग: te-रूप + もいいです = अनुमति ('कर सकते हैं / क्या मैं कर सकता हूँ?')।\nकब: अनुमति माँगना: はいってもいいですか (क्या मैं अंदर आ सकता हूँ?), しゃしんをとってもいいですか (क्या मैं फ़ोटो ले सकता हूँ?); देना: いいですよ / どうぞ (जाइए)।\nरूप: [क्रिया te-रूप] + もいいです। प्रश्न: 〜てもいいですか। निषेध: 〜てはいけません।\nटिप: てはいけません विपरीत है — 'नहीं करना चाहिए'। दोस्तों से सिर्फ いい? भी चलता है: たべていい?"
        ),
        Pattern(
            "jp18", "〜なければなりません — 'must ~'", "〜なければなりません — 「〜なければなりません」", "ja",
            "USAGE: Negative verb + なりません = obligation: 'must / have to ~'. Literally 'it won't do unless ~'.\nWHEN: Rules and duties: べんきょうしなければなりません (I must study), くすりをのまなければなりません (I must take medicine).\nFORM: [verb negative] + ば + なりません. Casual: 〜なくちゃ / 〜なきゃ (べんきょうしなきゃ). Softer: 〜なければいけません.\nTIP: The full form is long, so in speech Japanese almost always shortens it. Learn なきゃ first for everyday conversation.",
            "用途: 否定形 + なりません で「〜しなければならない」という義務を表します。文字どおりには「〜しないとだめ」。\nいつ: 規則や義務を言うとき。べんきょうしなければなりません、くすりをのまなければなりません。\n形: [動詞否定形] + ば + なりません。くだけた形: 〜なくちゃ / 〜なきゃ（べんきょうしなきゃ）。柔らかい形: 〜なければいけません。\nヒント: 長い形は話し言葉でほぼ必ず短くなります。まず なきゃ を覚えましょう。",
            listOf(
                PatternExample("📚", "べんきょうしなければなりません。", "benkyou shinakereba narimasen", "I must study.", "मुझे पढ़ाई करनी ही होगी।"),
                PatternExample("😴", "ねなければなりません。", "nenakereba narimasen", "I must sleep.", "मुझे सोना ही होगा।")
            ),
            "उपयोग: नकारात्मक क्रिया + なりません = बाध्यता ('करना ही होगा')। शाब्दिक अर्थ: 'जब तक न करें, नहीं चलेगा'।\nकब: नियम और कर्तव्य: べんきょうしなければなりません (मुझे पढ़ना ही होगा), くすりをのまなければなりません (मुझे दवा लेनी ही होगी)।\nरूप: [क्रिया का नकारात्मक] + ば + なりません। बोलचाल: 〜なくちゃ / 〜なきゃ (べんきょうしなきゃ)। नरम: 〜なければいけません।\nटिप: लंबा रूप बोलचाल में लगभग हमेशा छोटा होता है — पहले なきゃ सीखें।"
        ),
        Pattern(
            "jp19", "〜てから — 'after doing ~'", "〜てから — 「〜てから」", "ja",
            "USAGE: Te-form + から = 'after doing ~'. It expresses sequence: the first action is completed, then the next happens.\nWHEN: Ordering actions: ごはんをたべてから、でかけます (After eating, I'll go out), おふろにはいってから、ねます (I sleep after taking a bath).\nFORM: [verb te-form] + から, [next action]. Unlike plain て ('and then'), てから stresses that the first action is fully complete.\nTIP: It works the same in the past: たべてから、でかけました. Don't confuse this から with から meaning 'because' — that one follows a clause, not a te-form.",
            "用途: て形 + から で「〜してから」の意味です。先に〜して、その後に次の動作。\nいつ: 動作の順序を言うとき。ごはんをたべてから、でかけます、おふろにはいってから、ねます。\n形: [動詞て形] + から, [次の動作]。て と違い、てから は最初の動作が完全に終わることを強調します。\nヒント: 過去でも同じです。たべてから、でかけました。「理由のから」とは別物です。",
            listOf(
                PatternExample("🛁", "おふろにはいってから、ねます。", "ofuro ni haitte kara, nemasu", "I sleep after taking a bath.", "नहाने के बाद सोता हूँ।"),
                PatternExample("🍽️", "たべてから、おさらをあらいます。", "tabete kara, osara wo araimasu", "I wash the dishes after eating.", "खाने के बाद बर्तन धोता हूँ।")
            ),
            "उपयोग: te-रूप + から = 'करने के बाद'। पहला काम पूरा हो, फिर अगला।\nकब: क्रम बताने के लिए: ごはんをたべてから、でかけます (खाना खाकर फिर निकलूँगा), おふろにはいってから、ねます (नहाकर सोता हूँ)।\nरूप: [क्रिया te-रूप] + から, [अगला काम]। साधारण て से ज़्यादा ज़ोर इस पर कि पहला काम पूरा हुआ।\nटिप: भूतकाल में भी वही: たべてから、でかけました। 'क्योंकि' वाले から से अलग है।"
        ),
        Pattern(
            "jp20", "〜より のほうが — comparison", "〜より のほうが — 「〜より〜のほうが」", "ja",
            "USAGE: X より Y のほうが = 'Y is more ~ than X'. のほうが marks the preferred one; より marks the thing compared against.\nWHEN: Comparing two things: さかなよりにくのほうがすきです (I like meat more than fish), でんしゃのほうがはやいです (The train is faster).\nFORM: [A] より [B] のほうが [adjective/verb]. Example: [A] より [B] のほうがすきです.\nTIP: To ask the comparison question, use どちら: どちらがすきですか (Which do you like?). のほうが can be dropped when the comparison is obvious.",
            "用途: X より Y のほうが で「X よりも Y の方が〜」という比較を表します。のほうが が比較される側、より が比較の基準です。\nいつ: 二つを比べるとき。さかなよりにくのほうがすきです、でんしゃのほうがはやいです。\n形: [A] より [B] のほうが [形容詞・動詞]。\nヒント: 比較の疑問は どちら を使います。どちらがすきですか。「どちらが好き？」と聞けます。のほうが を省くこともあります。",
            listOf(
                PatternExample("🍣", "すしよりラーメンのほうがすきです。", "sushi yori raamen no hou ga suki desu", "I like ramen more than sushi.", "मुझे सुशी से ज़्यादा रामेन पसंद है।"),
                PatternExample("🐱", "ねこよりいぬのほうがかわいいです。", "neko yori inu no hou ga kawaii desu", "Dogs are cuter than cats.", "बिल्लियों से कुत्ते ज़्यादा प्यारे हैं।")
            ),
            "उपयोग: X より Y のほうが = 'Y, X से ज़्यादा ~ है'। のほうが पसंदीदा/बेहतर पक्ष, より तुलना का आधार।\nकब: दो चीज़ों की तुलना: さかなよりにくのほうがすきです (मुझे मछली से ज़्यादा मांस पसंद है), でんしゃのほうがはやいです (ट्रेन ज़्यादा तेज़ है)।\nरूप: [A] より [B] のほうが [विशेषण/क्रिया]।\nटिप: तुलना-प्रश्न どちら से: どちらがすきですか = 'कौन-सा ज़्यादा पसंद है?'। तुलना साफ़ हो तो のほうが छोड़ सकते हैं।"
        ),
        Pattern(
            "jp21", "〜がほしいです — 'I want (a thing)'", "〜がほしいです — 「〜が欲しいです」", "ja",
            "USAGE: ほしい (hoshii) = to want [a thing], marked with が. For wanting to DO something, use 〜たいです instead.\nWHEN: Talking about things you want: ほんがほしいです (I want a book), ねこがほしいです (I want a cat).\nFORM: [thing] が ほしいです. Negative: ほしくないです. Past: ほしかったです.\nTIP: ほしい is an い-adjective, so it conjugates like one. To say you want to SEE someone, use 〜にあいたい (want to meet) instead.",
            "用途: ほしい は「物が欲しい」の意味で、欲しいものを が で示します。動作が欲しいときは 〜たいです。\nいつ: 欲しい物を言うとき。ほんがほしいです、ねこがほしいです。\n形: [もの] が ほしいです。否定: ほしくないです。過去: ほしかったです。\nヒント: ほしい は い形容詞と同じ活用です。人に会いたいときは 〜にあいたい を使います。",
            listOf(
                PatternExample("📖", "ほんがほしいです。", "hon ga hoshii desu", "I want a book.", "मुझे किताब चाहिए।"),
                PatternExample("📱", "あたらしいけいたいがほしいです。", "atarashii keitai ga hoshii desu", "I want a new phone.", "मुझे नया फ़ोन चाहिए।")
            ),
            "उपयोग: ほしい = 'चाहिए' (किसी चीज़ के लिए), चीज़ が से चिह्नित होती है। काम करने की इच्छा के लिए 〜たいです।\nकब: चाहिए चीज़ें: ほんがほしいです (मुझे किताब चाहिए), ねこがほしいです (मुझे बिल्ली चाहिए)।\nरूप: [चीज़] が ほしいです। नकारात्मक: ほしくないです। भूतकाल: ほしかったです।\nटिप: ほしい い-विशेषण जैसा है, उसी तरह बदलता है। किसी से मिलना चाहिए तो 〜にあいたい।"
        ),
        Pattern(
            "jp22", "〜でした — past of です", "〜でした — 「〜でした」", "ja",
            "USAGE: です → でした makes the polite past: 'was / were'.\nWHEN: Describing the past: きのうはあめでした (Yesterday was rainy), がくせいでした (I was a student).\nFORM: [noun/adjective] でした. Negative past: ではありませんでした. Casual: じゃなかったです.\nTIP: For い-adjectives the past comes from the adjective itself: たかかったです (was expensive), never たかいでした.",
            "用途: です の過去形は でした です。「〜でした（だった）」。\nいつ: 過去のことを言うとき。きのうはあめでした、がくせいでした。\n形: [名詞・形容詞] でした。否定の過去: ではありませんでした。くだけた形: じゃなかったです。\nヒント: い形容詞は自分で過去形になります（たかかったです）。たかいでした は間違いです。",
            listOf(
                PatternExample("☔", "きのうはあめでした。", "kinou wa ame deshita", "Yesterday was rainy.", "कल बारिश थी।"),
                PatternExample("🎉", "たのしかったです。", "tanoshikatta desu", "It was fun.", "बहुत मज़ा आया।")
            ),
            "उपयोग: です का भूतकाल रूप でした है — 'था/थी'।\nकब: अतीत का वर्णन: きのうはあめでした (कल बारिश थी), がくせいでした (मैं विद्यार्थी था)।\nरूप: [संज्ञा/विशेषण] でした। नकारात्मक भूतकाल: ではありませんでした। कैज़ुअल: じゃなかったです।\nटिप: い-विशेषण अपना भूतकाल खुद बनाता है: たかかったです (महँगा था), たかいでした नहीं।"
        ),
        Pattern(
            "jp23", "〜てみます — 'try doing ~'", "〜てみます — 「〜てみます」", "ja",
            "USAGE: Te-form + みます = to try doing something.\nWHEN: Trying new experiences: さしみをたべてみます (I'll try eating sashimi), にほんごではなしてみます (I'll try speaking in Japanese).\nFORM: [verb te-form] + みます. Past: 〜てみました. Casual: 〜てみる.\nTIP: みます literally comes from みる 'to see' — imagine 'seeing how it goes'. Use it when you want to test or experience something new.",
            "用途: て形 + みます で「試しに〜する」という意味です。\nいつ: 何かを試すとき。さしみをたべてみます、にほんごではなしてみます。\n形: [動詞て形] + みます。過去: 〜てみました。くだけた形: 〜てみる。\nヒント: みます は「見る」から来ています。「やってみる」感覚です。新しいことに挑戦するときに使います。",
            listOf(
                PatternExample("🍜", "ラーメンをたべてみます。", "raamen wo tabete mimasu", "I'll try ramen.", "मैं रामेन चखूँगा।"),
                PatternExample("👕", "このふくをきてみます。", "kono fuku wo kite mimasu", "I'll try on these clothes.", "मैं ये कपड़े पहनकर देखूँगा।")
            ),
            "उपयोग: te-रूप + みます = 'कोशिश करके देखना'।\nकब: नई चीज़ आज़माते समय: さしみをたべてみます (मैं साशिमी खाकर देखूँगा), にほんごではなしてみます (मैं जापानी बोलकर देखूँगा)।\nरूप: [क्रिया te-रूप] + みます। भूतकाल: 〜てみました। कैज़ुअल: 〜てみる।\nटिप: みます 'देखना' से आया है — 'करके देखना' का भाव। नई चीज़ आज़माने के लिए।"
        ),
        Pattern(
            "jp24", "〜から — 'because ~'", "〜から — 「〜から」", "ja",
            "USAGE: Put から after the reason clause to say 'because'. The reason comes first in Japanese.\nWHEN: Explaining reasons: あついから、まどをあけます (I'll open the window because it's hot), いそがしいからいけません (I can't go because I'm busy).\nFORM: [reason] から, [result]. Very common in speech; can also stand alone at the end: どうして？ あついから (Why? Because it's hot).\nTIP: から can follow plain or polite forms (いそがしいですから). Don't confuse it with てから ('after doing').",
            "用途: 理由の文の最後に から を付けて「〜から（なので）」を表します。日本語では理由が先に来ます。\nいつ: 理由を説明するとき。あついから、まどをあけます、いそがしいからいけません。\n形: [理由] から, [結果]。話し言葉で非常によく使い、文末だけで「どうして？ あついから」とも言えます。\nヒント: から は普通形にも丁寧形にも付きます（いそがしいですから）。てから とは別物です。",
            listOf(
                PatternExample("🔥", "あついから、みずをのみます。", "atsui kara, mizu wo nomimasu", "Because it's hot, I drink water.", "गर्मी है इसलिए पानी पीता हूँ।"),
                PatternExample("🛒", "やすかったから、かいました。", "yasukatta kara, kaimashita", "Because it was cheap, I bought it.", "सस्ता था इसलिए खरीद लिया।")
            ),
            "उपयोग: कारण-वाक्य के अंत में から लगाकर 'क्योंकि' बताते हैं। जापानी में कारण पहले आता है।\nकब: कारण समझाते हुए: あついから、まどをあけます (गर्मी है इसलिए खिड़की खोलूँगा), いそがしいからいけません (व्यस्त हूँ इसलिए नहीं जा सकता)।\nरूप: [कारण] から, [परिणाम]। अकेले भी: どうして？ あついから (क्यों? क्योंकि गर्मी है)।\nटिप: から साधारण और विनम्र दोनों रूपों से जुड़ता है (いそがしいですから)। てから से भिन्न है।"
        ),
        Pattern(
            "jp25", "〜に — time particle", "〜に — 時間の助詞", "ja",
            "USAGE: に (ni) marks when something happens: at a clock time, on a day, in a month.\nWHEN: くじにおきます (I wake up at 9), げつようびにしごとがあります (I have work on Monday), さんがつににほんへいきます (I'll go to Japan in March).\nFORM: [time word] に [verb]. No に with relative words: きょう, あした, きのう, まいにち, らいしゅう.\nTIP: Rule of thumb: a specific number/date takes に; a relative word like 'today/tomorrow' takes none.",
            "用途: 時間を表す言葉に に を付けて「〜に」を表します。時刻・曜日・月など。\nいつ: くじにおきます、げつようびにしごとがあります、さんがつににほんへいきます。\n形: [時間の言葉] に [動詞]。きょう・あした・きのう・まいにち・らいしゅう など相対的な言葉には付けません。\nヒント: 具体的な日時（数字）には に、相対的な言葉（今日・明日など）には付けない、と覚えましょう。",
            listOf(
                PatternExample("⏰", "くじにおきます。", "kuji ni okimasu", "I wake up at 9.", "मैं नौ बजे उठता हूँ।"),
                PatternExample("🎂", "ろくがつにたんじょうびです。", "rokugatsu ni tanjoubi desu", "My birthday is in June.", "मेरा जन्मदिन जून में है।")
            ),
            "उपयोग: कण に समय दिखाता है — किस घड़ी, किस दिन, किस महीने।\nकब: くじにおきます (मैं 9 बजे उठता हूँ), げつようびにしごとがあります (सोमवार को काम है), さんがつににほんへいきます (मार्च में जापान जाऊँगा)।\nरूप: [समय-शब्द] に [क्रिया]। きょう/あした/きのう/まいにち/らいしゅう जैसे सापेक्ष शब्दों के साथ नहीं।\nटिप: नियम: तारीख़/संख्या हो तो に, 'आज/कल' जैसा सापेक्ष शब्द हो तो बिना に।"
        ),
        Pattern(
            "jp26", "〜で — by means of / at a place", "〜で — 手段・場所の助詞", "ja",
            "USAGE: で (de) marks the tool, means, or place of an action: 'by / with / at'.\nWHEN: Means/transport: でんしゃでいきます (go by train), ペンでかきます (write with a pen). Place of action: こうえんであそびます (play in the park), レストランでたべます (eat at a restaurant).\nFORM: [tool/means/place] で [verb]. For language: にほんごではなします (speak in Japanese).\nTIP: Distinguish で (place where an action happens) from に (place where something exists or goes): こうえんで = in the park (activity), こうえんに = to the park (destination).",
            "用途: で は手段（でんしゃで）、道具（ペンで）、場所（こうえんで）を表します。\nいつ: 交通手段や道具、動作の場所を言うとき。でんしゃでいきます、こうえんであそびます、レストランでたべます。\n形: [手段・道具・場所] で [動詞]。言語: にほんごではなします。\nヒント: 動作の場所は で、存在・行き先は に です。こうえんで（活動）と こうえんに（場所・行き先）を区別しましょう。",
            listOf(
                PatternExample("🚋", "でんしゃでいきます。", "densha de ikimasu", "I go by train.", "मैं ट्रेन से जाता हूँ।"),
                PatternExample("⚽", "こうえんでサッカーをします。", "kouen de sakkaa wo shimasu", "I play soccer in the park.", "मैं पार्क में फ़ुटबॉल खेलता हूँ।")
            ),
            "उपयोग: で (de) साधन, औज़ार या क्रिया का स्थान दिखाता है: 'से / से / में'।\nकब: साधन/यातायात: でんしゃでいきます (ट्रेन से जाना), ペンでかきます (कलम से लिखना)। स्थान: こうえんであそびます (पार्क में खेलना), レストランでたべます (रेस्तराँ में खाना)।\nरूप: [साधन/स्थान] で [क्रिया]। भाषा: にほんごではなします (जापानी में बोलना)।\nटिप: क्रिया का स्थान = で, अस्तित्व/गंतव्य = に। こうえんで (गतिविधि) बनाम こうえんに (स्थान)।"
        ),
        Pattern(
            "en13", "Present Simple — habits & facts", "現在形（習慣・事実）", "en",
            "USAGE: Present simple = habits, routines, and general facts: I drink tea every day, The sun rises in the east.\nWHEN: Daily routines (I wake up at 7), facts (Water boils at 100 degrees), schedules (The train leaves at 8).\nFORM: I/you/we/they + base verb; he/she/it + verb-s. Negative: don't / doesn't. Question: do / does.\nTIP: With he/she/it the verb takes -s (She works) — that's the only change. Frequency adverbs (always, usually, never) go before the verb.",
            "用途: 現在形は習慣・日課・一般的な事実を表します。I drink tea every day、The sun rises in the east。\nいつ: 日課（I wake up at 7）、事実（Water boils at 100 degrees）、予定表（The train leaves at 8）。\n形: I/you/we/they + 動詞の原形、he/she/it + 動詞 + s。否定: don't / doesn't。疑問: do / does。\nヒント: 三人称単数のとき動詞に s を付けます（She works）。頻度の副詞（always、usually、never）は動詞の前に置きます。",
            listOf(
                PatternExample("☕", "I drink tea every day.", "アイ ドリンク ティー エヴリ デイ", "まいにちおちゃをのみます。", "मैं हर दिन चाय पीता हूँ।"),
                PatternExample("🏫", "She works at a school.", "シー ワークス アット ア スクール", "かのじょはがっこうではたらいています。", "वह स्कूल में काम करती है।")
            ),
            "उपयोग: Present simple = आदतें, दिनचर्या और तथ्य: I drink tea every day, The sun rises in the east।\nकब: दिनचर्या (I wake up at 7), तथ्य (Water boils at 100 degrees), समय-सारणी (The train leaves at 8)।\nरूप: I/you/we/they + मूल क्रिया; he/she/it + क्रिया-s। नकारात्मक: don't/doesn't। प्रश्न: do/does।\nटिप: he/she/it के साथ क्रिया में -s लगता है (She works) — यही एकमात्र बदलाव। Frequency adverbs (always, usually, never) क्रिया से पहले।"
        ),
        Pattern(
            "en14", "Present Perfect — have/has + V3", "現在完了形", "en",
            "USAGE: have/has + past participle (V3) = present perfect. It links the past to now: experience, result, or recent events with just/already/yet.\nWHEN: Experience: I have been to Japan. Result: She has finished her homework. Recent news: He has just arrived.\nFORM: have/has + V3 (eaten, gone, seen). Negative: haven't / hasn't + V3. Question: Have you ~? / Has she ~?\nTIP: It pairs with yet (questions/negatives), just and already (positives). Never use a specific past time ('yesterday') with it — that takes past simple.",
            "用途: have/has + 過去分詞（V3）で現在完了形。過去が今につながっていることを表します。経験・結果・完了。\nいつ: 経験（I have been to Japan）、結果（She has finished her homework）、最近の出来事（He has just arrived）。\n形: have/has + V3（eaten、gone、seen）。否定: haven't / hasn't + V3。疑問: Have you ~? / Has she ~?\nヒント: just、already、yet とよく使います。yesterday など過去の明確な時間とは使いません（その場合は過去形）。",
            listOf(
                PatternExample("🍜", "I have eaten sushi.", "アイ ハヴ イートゥン スシ", "すしをたべたことがあります。", "मैंने सुशी खाई है।"),
                PatternExample("✅", "She has finished her work.", "シー ハズ フィニッシュト ハー ワーク", "かのじょはしごとをおえました。", "उसने अपना काम ख़त्म कर लिया है।")
            ),
            "उपयोग: have/has + तीसरा रूप (V3) = Present Perfect। अतीत को अभी से जोड़ता है — अनुभव, परिणाम, हाल की घटनाएँ।\nकब: अनुभव: I have been to Japan (मैं जापान जा चुका हूँ)। परिणाम: She has finished her homework। हाल: He has just arrived।\nरूप: have/has + V3 (eaten, gone, seen)। नकारात्मक: haven't/hasn't + V3। प्रश्न: Have you ~? / Has she ~?\nटिप: yet (प्रश्न/नकारात्मक), just/already (सकारात्मक) के साथ। 'yesterday' जैसे विशिष्ट भूत-समय के साथ कभी नहीं (वहाँ past simple)।"
        ),
        Pattern(
            "en15", "Present Perfect Continuous — have been + -ing", "現在完了進行形", "en",
            "USAGE: have/has been + -ing = an action that started in the past and is still going on, emphasizing the duration.\nWHEN: Ongoing actions with duration: I have been studying for 2 hours, She has been working here since 2020. Also for recent activity with visible results: You have been crying.\nFORM: have/has been + verb-ing. Negative: haven't been / hasn't been + -ing. Question: Have you been ~ing?\nTIP: Use 'for' + a period (for 2 hours) and 'since' + a starting point (since 2020). Compare: present perfect (finished: I have read the book) vs continuous (ongoing: I have been reading).",
            "用途: have/has been + 動詞ing で、過去に始まって今も続いている動作（継続時間を強調）を表します。\nいつ: 継続している動作。I have been studying for 2 hours、She has been working here since 2020。結果が見える最近の動作（You have been crying）にも。\n形: have/has been + 動詞ing。否定: haven't been / hasn't been + ing。疑問: Have you been ~ing?\nヒント: 期間は for（for 2 hours）、起点は since（since 2020）。完了（I have read）と継続（I have been reading）を比べましょう。",
            listOf(
                PatternExample("📚", "I have been studying for two hours.", "アイ ハヴ ビーン スタディング フォー トゥー アワーズ", "にじかんべんきょうしています。", "मैं दो घंटे से पढ़ रहा हूँ।"),
                PatternExample("🌧️", "It has been raining all day.", "イット ハズ ビーン レイニング オール デイ", "いちにちじゅうあめがふっています。", "पूरे दिन बारिश हो रही है।")
            ),
            "उपयोग: have/has been + -ing = अतीत में शुरू हुआ काम जो अभी भी चल रहा है (अवधि पर ज़ोर)।\nकब: चल रहे काम: I have been studying for 2 hours (मैं 2 घंटे से पढ़ रहा हूँ), She has been working here since 2020। दिखते परिणाम वाला हालिया काम: You have been crying।\nरूप: have/has been + क्रिया-ing। नकारात्मक: haven't/hasn't been + -ing। प्रश्न: Have you been ~ing?\nटिप: अवधि के लिए for (for 2 hours), शुरुआत बिंदु के लिए since (since 2020)। पूर्ण (I have read) बनाम जारी (I have been reading)।"
        ),
        Pattern(
            "en16", "Past Continuous — was/were + -ing", "過去進行形", "en",
            "USAGE: was/were + -ing = an action in progress at a past moment.\nWHEN: Background action interrupted by another event: I was reading when you called. Two simultaneous actions: She was cooking while I was studying.\nFORM: was (I/he/she/it) / were (you/we/they) + verb-ing. Negative: wasn't / weren't. Question: Was she ~ing?\nTIP: Pair it with past simple for interruption: was doing + when + did. The -ing action is the 'background'; the simple past is the 'event'.",
            "用途: was/were + 動詞ing で、過去のある時点で進行中だった動作を表します。\nいつ: 別の出来事に遮られる背景動作（I was reading when you called）、同時進行（She was cooking while I was studying）。\n形: was（I/he/she/it）/ were（you/we/they）+ 動詞ing。否定: wasn't / weren't。疑問: Was she ~ing?\nヒント: 過去形と組み合わせて「〜していたときに〜した」を作ります。ing形が背景、過去形が出来事です。",
            listOf(
                PatternExample("📖", "I was reading when you called.", "アイ ワズ リーディング ウェン ユー コールド", "あなたがでんわしたときよんでいました。", "जब तुमने फ़ोन किया मैं पढ़ रहा था।"),
                PatternExample("🍳", "She was cooking dinner.", "シー ワズ クッキング ディナー", "かのじょはばんごはんをつくっていました。", "वह रात का खाना बना रही थी।")
            ),
            "उपयोग: was/were + -ing = अतीत के किसी समय चल रही क्रिया।\nकब: बीच में टोकने वाली घटना वाला पृष्ठभूमि काम: I was reading when you called (जब तुमने फ़ोन किया मैं पढ़ रहा था)। साथ-साथ: She was cooking while I was studying।\nरूप: was (I/he/she/it) / were (you/we/they) + क्रिया-ing। नकारात्मक: wasn't/weren't। प्रश्न: Was she ~ing?\nटिप: past simple के साथ: was doing + when + did। -ing पृष्ठभूमि है, past simple घटना।"
        ),
        Pattern(
            "en17", "Past Perfect — had + V3", "過去完了形", "en",
            "USAGE: had + past participle (V3) = the earlier of two past events: 'before X happened, Y had already happened'.\nWHEN: Ordering past events: When I arrived, the movie had already started. She had finished her homework before dinner.\nFORM: had + V3 (had gone, had seen). Negative: hadn't + V3. Question: Had you ~?\nTIP: You only need it when the order of two past actions matters. If the sequence is clear from 'before/after', simple past is often fine: After I ate, I slept.",
            "用途: had + 過去分詞（V3）で、二つの過去の出来事のうち「より前に起きた方」を表します。\nいつ: 過去の順序を明確にしたいとき。When I arrived, the movie had already started、She had finished her homework before dinner。\n形: had + V3（had gone、had seen）。否定: hadn't + V3。疑問: Had you ~?\nヒント: 前後関係が before/after で明らかなときは過去形で十分です。After I ate, I slept。",
            listOf(
                PatternExample("🎉", "I had already eaten before the party.", "アイ ハド オールレディ イートゥン ビフォー ザ パーティー", "パーティーのまえにすでにたべていました。", "पार्टी से पहले मैं खा चुका था।"),
                PatternExample("🏠", "They had left when we arrived.", "ゼイ ハド レフト ウェン ウィー アライヴド", "ついたときかれらはもうでていました。", "जब हम पहुँचे वे जा चुके थे।")
            ),
            "उपयोग: had + तीसरा रूप (V3) = दो भूतकाल की घटनाओं में से पहले वाली।\nकब: क्रम स्पष्ट करने के लिए: When I arrived, the movie had already started (जब मैं पहुँचा, फ़िल्म शुरू हो चुकी थी), She had finished her homework before dinner।\nरूप: had + V3 (had gone, had seen)। नकारात्मक: hadn't + V3। प्रश्न: Had you ~?\nटिप: सिर्फ तब चाहिए जब क्रम मायने रखे। before/after से क्रम साफ़ हो तो past simple ही काफ़ी: After I ate, I slept।"
        ),
        Pattern(
            "en18", "will — future predictions & decisions", "will 未来形", "en",
            "USAGE: will + verb = future: predictions, promises, and decisions made at the moment of speaking.\nWHEN: Instant decisions (I'll take it!), promises (I will help you), predictions (It will rain tomorrow), offers (I'll open the door).\nFORM: will + base verb. Contraction: I'll, she'll, we'll. Negative: won't. Question: Will you ~?\nTIP: Use will for 'at the moment' decisions; use going to for pre-arranged plans. Both are correct — the difference is how decided the plan is.",
            "用途: will + 動詞の原形 で未来を表します。予測・約束・その場の決断。\nいつ: その場の決断（I'll take it!）、約束（I will help you）、予測（It will rain tomorrow）、申し出（I'll open the door）。\n形: will + 動詞の原形。短縮形: I'll、she'll、we'll。否定: won't。疑問: Will you ~?\nヒント: その場の決断には will、前もって決めた予定には going to を使います。どちらも正しい未来形です。",
            listOf(
                PatternExample("🛒", "I'll take this one.", "アイ ウィル テイク ジス ワン", "これにします。", "मैं यह लूँगा।"),
                PatternExample("🌧️", "It will rain tomorrow.", "イット ウィル レイン トゥモロー", "あしたはあめでしょう。", "कल बारिश होगी।")
            ),
            "उपयोग: will + क्रिया = भविष्य: भविष्यवाणी, वादे, और पल भर के फ़ैसले।\nकब: पल भर का फ़ैसला (I'll take it!), वादा (I will help you), भविष्यवाणी (It will rain tomorrow), पेशकश (I'll open the door)।\nरूप: will + मूल क्रिया। संक्षिप्त: I'll, she'll, we'll। नकारात्मक: won't। प्रश्न: Will you ~?\nटिप: पल भर का फ़ैसला = will, पहले से तय योजना = going to। दोनों सही हैं — फ़र्क योजना की पक्कीपन में।"
        ),
        Pattern(
            "en19", "could / would / may — polite requests", "丁寧な依頼（could / would / may）", "en",
            "USAGE: could, would, and may make requests softer and more polite than can. May is the most formal; could is the most common.\nWHEN: Could you open the door? Would you help me? May I come in? Also for offers: Could I get you some coffee?\nFORM: Could/Would + you + verb? | May + I + verb? They are all followed by the base verb.\nTIP: The politeness scale: Can (informal) → Could/Would (polite) → May (very formal). Add 'please' for extra politeness.",
            "用途: could、would、may は can より柔らかく丁寧なお願いです。may が最も格式ばり、could が最もよく使われます。\nいつ: Could you open the door?、Would you help me?、May I come in?。申し出（Could I get you some coffee?）にも。\n形: Could/Would + you + 動詞の原形 | May + I + 動詞の原形。すべて原形を取ります。\nヒント: 丁寧さの順: Can（くだけた）→ Could/Would（丁寧）→ May（非常に格式ばる）。please を付けるとさらに丁寧です。",
            listOf(
                PatternExample("🚪", "Could you open the door?", "クッド ユー オウプン ザ ドア", "ドアをあけていただけますか。", "क्या आप दरवाज़ा खोल सकते हैं?"),
                PatternExample("🆘", "Would you help me?", "ウッド ユー ヘルプ ミー", "てつだっていただけますか。", "क्या आप मेरी मदद करेंगे?")
            ),
            "उपयोग: could, would, may अनुरोध को can से नरम/विनम्र बनाते हैं। may सबसे औपचारिक, could सबसे आम।\nकब: Could you open the door? (क्या आप दरवाज़ा खोल सकते हैं?) Would you help me? May I come in? पेशकश: Could I get you some coffee?\nरूप: Could/Would + you + क्रिया? | May + I + क्रिया? सबके साथ मूल क्रिया।\nटिप: विनम्रता: Can (अनौपचारिक) → Could/Would (विनम्र) → May (बहुत औपचारिक)। 'please' और विनम्र बनाता है।"
        ),
        Pattern(
            "en20", "must / have to — obligation", "must / have to（義務）", "en",
            "USAGE: must + verb (strong, often personal obligation): I must study. have to (everyday external obligation): I have to go.\nWHEN: Rules: You must wear a helmet. Duties: She has to work tomorrow. Strong advice: You must see this movie!\nFORM: must + base verb | have to + base verb (he/she/it: has to). Negative: mustn't (= not allowed), don't have to (= not necessary).\nTIP: Big difference: mustn't = forbidden (You mustn't smoke here), don't have to = no obligation (You don't have to come). For the past, use had to: I had to leave early.",
            "用途: must + 動詞の原形 は強い義務（自分の意志）、have to は日常的な義務（外部から）です。\nいつ: 規則（You must wear a helmet）、義務（She has to work tomorrow）、強い助言（You must see this movie!）。\n形: must + 動詞の原形 | have to + 動詞の原形（he/she/it は has to）。否定: mustn't（禁止）、don't have to（不要）。\nヒント: mustn't は「〜してはいけない」、don't have to は「〜する必要はない」。過去形は had to です。I had to leave early。",
            listOf(
                PatternExample("💊", "I must take my medicine.", "アイ マスト テイク マイ メディスン", "くすりをのまなければなりません。", "मुझे दवा लेनी ही होगी।"),
                PatternExample("⏰", "I have to go now.", "アイ ハヴ トゥ ゴウ ナウ", "いまいかなくてはなりません。", "मुझे अभी जाना होगा।")
            ),
            "उपयोग: must + क्रिया (मज़बूत, निजी बाध्यता): I must study। have to (रोज़मर्रा, बाहरी बाध्यता): I have to go।\nकब: नियम: You must wear a helmet। कर्तव्य: She has to work tomorrow। ज़ोरदार सलाह: You must see this movie!\nरूप: must + मूल क्रिया | have to + मूल क्रिया (he/she/it: has to)। नकारात्मक: mustn't (मना है), don't have to (ज़रूरी नहीं)।\nटिप: mustn't = वर्जित (You mustn't smoke here), don't have to = ज़रूरी नहीं (You don't have to come)। भूतकाल: had to (I had to leave early)।"
        ),
        Pattern(
            "en21", "should — advice", "should（助言）", "en",
            "USAGE: should + verb = advice or recommendation: 'it's a good idea to ~'.\nWHEN: Giving advice: You should rest. Asking for advice: What should I do? Recommendations: You should try the ramen.\nFORM: should + base verb. Negative: shouldn't + verb (You shouldn't worry). Question: Should I ~? / Should we ~?\nTIP: should is softer than must — it's advice, not obligation. Compare: You must go (no choice) vs You should go (recommended).",
            "用途: should + 動詞の原形 で助言・推奨「〜するべき」を表します。\nいつ: 助言（You should rest）、相談（What should I do?）、おすすめ（You should try the ramen）。\n形: should + 動詞の原形。否定: shouldn't + 動詞（You shouldn't worry）。疑問: Should I ~?\nヒント: should は must より柔らかく、助言であって義務ではありません。You must go（選択の余地なし）vs You should go（推奨）。",
            listOf(
                PatternExample("😴", "You should rest.", "ユー シュッド レスト", "やすむべきです。", "तुम्हें आराम करना चाहिए।"),
                PatternExample("📖", "He should study more.", "ヒー シュッド スタディ モア", "かれはもっとべんきょうすべきです。", "उसे और पढ़ना चाहिए।")
            ),
            "उपयोग: should + क्रिया = सलाह या सुझाव: 'करना चाहिए'।\nकब: सलाह: You should rest (तुम्हें आराम करना चाहिए)। सलाह माँगना: What should I do? सुझाव: You should try the ramen।\nरूप: should + मूल क्रिया। नकारात्मक: shouldn't + क्रिया (You shouldn't worry)। प्रश्न: Should I ~?\nटिप: should, must से नरम है — सलाह, बाध्यता नहीं। You must go (कोई विकल्प नहीं) बनाम You should go (सुझाव)।"
        ),
        Pattern(
            "en22", "Superlatives — the -est / most", "最上級（the -est / most）", "en",
            "USAGE: Superlatives = the highest degree: short words take -est (biggest), long words take most (most beautiful). Always with 'the'.\nWHEN: Comparing 3+ things: She is the tallest in her class, This is the most interesting book I've read.\nFORM: the + short adj + est | the + most + long adj. Spelling: big→biggest, easy→easiest. Irregular: good→best, bad→worst, far→farthest.\nTIP: Use 'in' + group (the tallest in the class) or 'of' + group (the best of all). Don't forget 'the' — it's required.",
            "用途: 最上級は「最も〜」を表します。短い形容詞は -est（biggest）、長い形容詞は most（most beautiful）。必ず the を付けます。\nいつ: 3つ以上を比べるとき。She is the tallest in her class、This is the most interesting book I've read。\n形: the + 短い形容詞 + est | the + most + 長い形容詞。綴り: big→biggest、easy→easiest。不規則: good→best、bad→worst。\nヒント: グループは in（the tallest in the class）か of（the best of all）で示します。the を忘れないでください。",
            listOf(
                PatternExample("🏔️", "This is the highest mountain.", "ジス イズ ザ ハイエスト マウンテン", "これはいちばんたかいやまです。", "यह सबसे ऊँचा पहाड़ है।"),
                PatternExample("🌸", "She is the kindest person I know.", "シー イズ ザ カインデスト パーソン アイ ノウ", "かのじょはいちばんやさしいひとです。", "वह मेरी जानी सबसे दयालु इंसान है।")
            ),
            "उपयोग: Superlative = सबसे ज़्यादा: छोटे शब्द -est (biggest), लंबे शब्द most (most beautiful)। हमेशा 'the' के साथ।\nकब: 3+ चीज़ों की तुलना: She is the tallest in her class (वह कक्षा में सबसे लंबी है), This is the most interesting book I've read।\nरूप: the + छोटा विशेषण + est | the + most + लंबा विशेषण। वर्तनी: big→biggest, easy→easiest। अनियमित: good→best, bad→worst।\nटिप: समूह के लिए in (the tallest in the class) या of (the best of all)। 'the' अनिवार्य है।"
        ),
        Pattern(
            "en23", "Conditionals — if sentences", "条件文（if）", "en",
            "USAGE: If-sentences show conditions and results. There are several types for real and unreal situations.\nWHEN: 1st (real/future): If it rains, I will stay home. 2nd (hypothetical now): If I were rich, I would travel. 3rd (past, unreal): If I had known, I would have come.\nFORM: 1st: if + present, will + verb. 2nd: if + past, would + verb (were for all persons). 3rd: if + had + V3, would have + V3.\nTIP: The order can flip: I will stay home if it rains. Note 'I were' (not 'I was') in the 2nd conditional. The 3rd conditional = regrets about the past.",
            "用途: if 文で条件と結果を表します。現実・非現実でいくつかの型があります。\nいつ: 1st（現実・未来）: If it rains, I will stay home。2nd（仮定）: If I were rich, I would travel。3rd（過去の仮定）: If I had known, I would have come。\n形: 1st: if + 現在形, will + 動詞。2nd: if + 過去形, would + 動詞（すべての人称で were）。3rd: if + had + V3, would have + V3。\nヒント: 順序は入れ替え可能です（I will stay home if it rains）。2nd では I was ではなく I were。3rd は過去の後悔です。",
            listOf(
                PatternExample("🌧️", "If it rains, I will stay home.", "イフ イット レインズ アイ ウィル ステイ ホーム", "あめならいえにいます。", "अगर बारिश हुई तो मैं घर पर रहूँगा।"),
                PatternExample("💰", "If I were rich, I would travel.", "イフ アイ ワー リッチ アイ ウッド トラベル", "おかねもちならりょこうするのに。", "अगर मैं अमीर होता तो यात्रा करता।")
            ),
            "उपयोग: if-वाक्य = शर्त और परिणाम। वास्तविक और काल्पनिक स्थितियों के कई प्रकार।\nकब: 1st (वास्तविक/भविष्य): If it rains, I will stay home। 2nd (काल्पनिक): If I were rich, I would travel। 3rd (भूतकाल, अवास्तविक): If I had known, I would have come।\nरूप: 1st: if + वर्तमान, will + क्रिया। 2nd: if + भूतकाल, would + क्रिया (सबके लिए were)। 3rd: if + had + V3, would have + V3।\nटिप: क्रम बदल सकता है: I will stay home if it rains। 2nd में 'I were' (I was नहीं)। 3rd = अतीत का पछतावा।"
        ),
        Pattern(
            "en24", "Passive voice — be + past participle", "受動態", "en",
            "USAGE: Passive voice: be + past participle (V3). It focuses on the action or the receiver, not the doer: The cake was eaten.\nWHEN: When the doer is unknown or unimportant: My bike was stolen. When focusing on the receiver: The report was finished yesterday. By + doer: The cake was eaten by the dog.\nFORM: be (in any tense) + V3: is eaten, was eaten, will be eaten, has been eaten. Negative/Question: standard be rules.\nTIP: Only transitive verbs (with an object) can be passive. Don't overuse it — active voice is usually clearer and more natural in English.",
            "用途: 受動態は be動詞 + 過去分詞（V3）で表します。動作や受ける側に焦点を当てます。The cake was eaten。\nいつ: 動作主が不明・重要でないとき（My bike was stolen）、受ける側に焦点（The report was finished yesterday）。動作主は by で示します。\n形: 時制に応じた be + V3。is eaten、was eaten、will be eaten、has been eaten。\nヒント: 受動態にできるのは他動詞だけです。使いすぎは避けましょう。英語では能動態のほうが自然なことが多いです。",
            listOf(
                PatternExample("🍰", "The cake was eaten.", "ザ ケイク ワズ イートゥン", "ケーキはたべられました。", "केक खा लिया गया।"),
                PatternExample("🏗️", "This bridge was built in 2000.", "ジス ブリッジ ワズ ビルト イン トゥー サウザンド", "このはしは2000ねんにつくられました。", "यह पुल सन् 2000 में बनाया गया था।")
            ),
            "उपयोग: Passive voice = be + तीसरा रूप (V3)। क्रिया या कर्म पर ध्यान, कर्ता पर नहीं: The cake was eaten (केक खाया गया)।\nकब: कर्ता अज्ञात/महत्वहीन: My bike was stolen। कर्म पर ध्यान: The report was finished yesterday। कर्ता by से: The cake was eaten by the dog।\nरूप: be (किसी भी काल में) + V3: is eaten, was eaten, will be eaten, has been eaten।\nटिप: सिर्फ सकर्मक क्रियाएँ (कर्म वाली) passive बन सकती हैं। ज़्यादा मत लगाएँ — active ज़्यादा स्वाभाविक।"
        ),
        Pattern(
            "en25", "Reported speech — 'she said…'", "間接話法", "en",
            "USAGE: Reported speech tells what someone said without quoting: She said (that) she was tired.\nWHEN: Reporting statements: He said he was busy. Reporting questions: She asked if I was free. Reporting commands: He told me to wait.\nFORM: Tense shifts back one: am→was, will→would, can→could, have→had. 'that' is optional. Pronouns and time words also shift (today→that day, here→there).\nTIP: Direct quote: She said, 'I am tired' → Reported: She said she was tired. If the reporting verb is present (says), the tense doesn't shift: She says she is tired.",
            "用途: 間接話法は誰かの発言を引用符なしで伝えます。She said (that) she was tired。\nいつ: 発言の伝達（He said he was busy）、疑問の伝達（She asked if I was free）、命令の伝達（He told me to wait）。\n形: 時制を一つ過去にずらします（am→was、will→would、can→could、have→had）。that は省略可能。代名詞や時を表す語も変わります（today→that day）。\nヒント: 直接話法: She said, 'I am tired' → 間接話法: She said she was tired。伝える動詞が現在形（says）なら時制は変わりません。",
            listOf(
                PatternExample("🗣️", "She said she was tired.", "シー セッド シー ワズ タイアド", "かのじょはつかれたと言いました。", "उसने कहा कि वह थकी हुई थी।"),
                PatternExample("🧑", "He told me he would come.", "ヒー トールド ミー ヒー ウッド カム", "かれはくると言いました。", "उसने मुझसे कहा कि वह आएगा।")
            ),
            "उपयोग: Reported speech = किसी की बात बिना उद्धरण के बताना: She said (that) she was tired (उसने कहा वह थकी थी)।\nकब: बातें: He said he was busy। प्रश्न: She asked if I was free। आदेश: He told me to wait।\nरूप: काल एक पीछे: am→was, will→would, can→could, have→had। 'that' वैकल्पिक। सर्वनाम/समय-शब्द भी बदलते हैं (today→that day)।\nटिप: प्रत्यक्ष: She said, 'I am tired' → परोक्ष: She said she was tired। कहने वाली क्रिया वर्तमान (says) हो तो काल नहीं बदलता।"
        ),
        Pattern(
            "en26", "Gerunds & infinitives — -ing vs to + verb", "動名詞と不定詞", "en",
            "USAGE: Some verbs are followed by a gerund (-ing), others by an infinitive (to + verb): I enjoy reading, I want to go.\nWHEN: Gerund after: enjoy, finish, mind, suggest, avoid, keep. Infinitive after: want, decide, hope, plan, need, learn. Both with similar meaning: begin, start, like, love. Meaning changes: stop, remember, try.\nFORM: verb + -ing | verb + to + base. As subject: Swimming is fun. After prepositions: I'm good at cooking.\nTIP: Meaning-change verbs matter: remember doing (past memory) vs remember to do (not forget), stop smoking (quit) vs stop to smoke (pause).",
            "用途: 動詞によって、-ing（動名詞）か to 不定詞のどちらかを取ります。I enjoy reading、I want to go。\nいつ: -ing を取る動詞: enjoy、finish、mind、suggest。to を取る動詞: want、decide、hope、plan、need。どちらも取るもの: begin、start、like。\n形: 動詞 + ing | 動詞 + to + 動詞の原形。主語: Swimming is fun。前置詞の後: I'm good at cooking。\nヒント: 意味が変わる動詞に注意。remember doing（覚えている）と remember to do（忘れない）、stop smoking（やめる）と stop to smoke（やめて吸う）。",
            listOf(
                PatternExample("📚", "I enjoy reading books.", "アイ エンジョイ リーディング ブックス", "ほんをよむのがすきです。", "मुझे किताबें पढ़ना अच्छा लगता है।"),
                PatternExample("✈️", "She wants to travel.", "シー ウォンツ トゥ トラベル", "かのじょはりょこうしたいです。", "वह यात्रा करना चाहती है।")
            ),
            "उपयोग: कुछ क्रियाओं के साथ gerund (-ing), कुछ के साथ infinitive (to + क्रिया): I enjoy reading, I want to go।\nकब: -ing के साथ: enjoy, finish, mind, suggest। to के साथ: want, decide, hope, plan, need। दोनों: begin, start, like। अर्थ बदलते: stop, remember, try।\nरूप: क्रिया + -ing | क्रिया + to + मूल क्रिया। कर्ता के रूप में: Swimming is fun। preposition के बाद: I'm good at cooking।\nटिप: अर्थ बदलने वाले याद रखें: remember doing (याद है) बनाम remember to do (न भूलूँ), stop smoking (छोड़ना) बनाम stop to smoke (रुककर पीना)।"
        ),
        Pattern(
            "en27", "too / enough", "too / enough", "en",
            "USAGE: too + adjective = more than needed (negative): too hot, too expensive. adjective + enough = sufficient: old enough, big enough.\nWHEN: Problems and limits: The soup is too salty. Sufficiency: He is tall enough to reach the shelf. With nouns: too much sugar, enough time.\nFORM: too + adj | adj + enough | too much/many + noun | enough + noun. Negative form: not + adj + enough (not old enough).\nTIP: Word order differs: too comes BEFORE the adjective, enough comes AFTER. For nouns: enough time (before the noun) but big enough (after the adjective).",
            "用途: too + 形容詞 は「〜すぎる」（マイナスの意味）、形容詞 + enough は「十分〜」を表します。\nいつ: 問題・限界（The soup is too salty）、十分さ（He is tall enough to reach the shelf）。名詞と: too much sugar、enough time。\n形: too + 形容詞 | 形容詞 + enough | too much/many + 名詞 | enough + 名詞。\nヒント: 語順が違います。too は形容詞の前、enough は形容詞の後ろ。名詞には enough time のように前です。",
            listOf(
                PatternExample("🔥", "This tea is too hot.", "ジス ティー イズ トゥー ホット", "このおちゃはあつすぎます。", "यह चाय बहुत गर्म है।"),
                PatternExample("🎂", "He is old enough to drive.", "ヒー イズ オウルド イナフ トゥ ドライヴ", "かれはうんてんできるおとしです。", "वह गाड़ी चलाने लायक़ है।")
            ),
            "उपयोग: too + विशेषण = ज़रूरत से ज़्यादा (नकारात्मक): too hot। विशेषण + enough = पर्याप्त: old enough।\nकब: समस्या/सीमा: The soup is too salty (सूप बहुत नमकीन है)। पर्याप्तता: He is tall enough to reach the shelf। संज्ञा के साथ: too much sugar, enough time।\nरूप: too + विशेषण | विशेषण + enough | too much/many + संज्ञा | enough + संज्ञा।\nटिप: क्रम: too विशेषण से पहले, enough बाद में। संज्ञा के साथ enough पहले: enough time, big enough।"
        ),
        Pattern(
            "en28", "used to — past habits", "used to（過去の習慣）", "en",
            "USAGE: used to + verb = a past habit or state that no longer happens: I used to play soccer.\nWHEN: Past routines and states now gone: I used to live in Osaka, She used to be shy, We used to eat out every Sunday.\nFORM: used to + base verb. Negative: didn't use to (I didn't use to like coffee). Question: Did you use to ~?\nTIP: Distinguish: be used to + -ing = accustomed to (I'm used to getting up early) — different meaning, different form. In questions/negatives, 'used' becomes 'use'.",
            "用途: used to + 動詞の原形 で、過去の習慣・状態（今はしていない）を表します。I used to play soccer。\nいつ: 過去の習慣・状態。I used to live in Osaka、She used to be shy、We used to eat out every Sunday。\n形: used to + 動詞の原形。否定: didn't use to。疑問: Did you use to ~?\nヒント: be used to + ing（慣れている）とは別物です。I'm used to getting up early。否定・疑問では used → use になります。",
            listOf(
                PatternExample("⚽", "I used to play soccer.", "アイ ユーストゥ プレイ サッカー", "むかしサッカーをしていました。", "मैं पहले फ़ुटबॉल खेलता था।"),
                PatternExample("🌙", "She used to live here.", "シー ユーストゥ リヴ ヒア", "かのじょはむかしここにすんでいました。", "वह पहले यहाँ रहती थी।")
            ),
            "उपयोग: used to + क्रिया = वह आदत/अवस्था जो पहले थी, अब नहीं: I used to play soccer (मैं पहले फ़ुटबॉल खेलता था)।\nकब: बीती आदतें/अवस्थाएँ: I used to live in Osaka, She used to be shy, We used to eat out every Sunday।\nरूप: used to + मूल क्रिया। नकारात्मक: didn't use to। प्रश्न: Did you use to ~?\nटिप: be used to + -ing = 'आदी होना' (I'm used to getting up early) — अलग अर्थ, अलग रूप। नकारात्मक/प्रश्न में 'use'।"
        ),
        Pattern(
            "en29", "Question tags — '…, isn't it?'", "付加疑問文", "en",
            "USAGE: A question tag is a short question added to the end of a statement to check or confirm: You're tired, aren't you?\nWHEN: Confirming information (expecting agreement): It's a nice day, isn't it? Checking uncertain info: You haven't seen my keys, have you?\nFORM: Positive statement + negative tag | negative statement + positive tag. Use the same auxiliary: is/are/was/were, do/does/did, have/has, can, will, should.\nTIP: If there's no auxiliary, use do/does/did: She lives here, doesn't she? The tag for 'I am' is 'aren't I'. Answer with yes/no matching the fact, not the tag.",
            "用途: 付加疑問は文末に付ける短い確認の疑問です。You're tired, aren't you?\nいつ: 同意を求める確認（It's a nice day, isn't it?）、確かでない情報の確認（You haven't seen my keys, have you?）。\n形: 肯定文 + 否定の付加疑問 | 否定文 + 肯定の付加疑問。助動詞を使います（is、do、have、can、will、should など）。\nヒント: 助動詞がないときは do/does/did を使います。She lives here, doesn't she? I am の付加疑問は aren't I。",
            listOf(
                PatternExample("🥱", "You're tired, aren't you?", "ヨーア タイアド アーント ユー", "つかれていますね。", "तुम थके हुए हो, है ना?"),
                PatternExample("🌞", "It's a nice day, isn't it?", "イッツ ア ナイス デイ イズント イット", "いいおてんきですね。", "आज अच्छा दिन है, है ना?")
            ),
            "उपयोग: Question tag = पुष्टि के लिए वाक्य के अंत में छोटा प्रश्न: You're tired, aren't you? (तुम थके हो, है ना?)\nकब: सहमति की उम्मीद में: It's a nice day, isn't it? अनिश्चित जानकारी की जाँच: You haven't seen my keys, have you?\nरूप: सकारात्मक + नकारात्मक tag | नकारात्मक + सकारात्मक tag। वही auxiliary: is, do, have, can, will।\nटिप: auxiliary न हो तो do/does/did: She lives here, doesn't she? 'I am' का tag 'aren't I'। उत्तर तथ्य के हिसाब से दें, tag के हिसाब से नहीं।"
        ),
        Pattern(
            "en30", "Relative clauses — who / which / that", "関係詞（who / which / that）", "en",
            "USAGE: Relative clauses add information to a noun: the person who called, the book which/that I bought.\nWHEN: Defining (essential info): The man who lives next door is a doctor. Non-defining (extra info, with commas): My brother, who lives in Tokyo, is an engineer.\nFORM: person + who/that | thing + which/that. Defining clause: no commas. Non-defining: commas, cannot use 'that'.\nTIP: In defining clauses you can often drop who/which/that when it's the object: the book (that) I bought. People take who/that; things take which/that.",
            "用途: 関係詞節は名詞に情報を付け足します。the person who called、the book which/that I bought。\nいつ: 限定（必須情報）: The man who lives next door is a doctor。非限定（追加情報・コンマ付き）: My brother, who lives in Tokyo, is an engineer。\n形: 人 + who/that | 物 + which/that。限定節: コンマなし。非限定節: コンマ付きで that は使えません。\nヒント: 限定節では目的語の who/which/that は省略できます。the book (that) I bought。人には who、物には which です。",
            listOf(
                PatternExample("📞", "The person who called is my friend.", "ザ パーソン フー コールド イズ マイ フレンド", "でんわしたひとはともだちです。", "जिसने फ़ोन किया वह मेरा दोस्त है।"),
                PatternExample("📖", "The book that I bought is interesting.", "ザ ブック ザット アイ ボート イズ インタレスティング", "かったほんはおもしろいです。", "जो किताब मैंने खरीदी वह दिलचस्प है।")
            ),
            "उपयोग: Relative clause संज्ञा में जानकारी जोड़ता है: the person who called (जिसने फ़ोन किया), the book which/that I bought (जो मैंने खरीदी)।\nकब: Defining (आवश्यक): The man who lives next door is a doctor। Non-defining (अतिरिक्त, कॉमा के साथ): My brother, who lives in Tokyo, is an engineer।\nरूप: व्यक्ति + who/that | वस्तु + which/that। Defining में कॉमा नहीं; non-defining में कॉमा, और that नहीं।\nटिप: Defining में object वाला who/which/that हटा सकते हैं: the book (that) I bought। व्यक्ति = who, वस्तु = which।"
        ),
    ) + JpN5.patterns + JpN4.patterns + JpN3.patterns + JpN2.patterns + JpN1.patterns +
        EnA1.patterns + EnA2.patterns + EnB1.patterns + EnB2.patterns + EnC1.patterns + EnC2.patterns +
        Genki.patterns + Jfz.patterns
}
